/**
 * =============================================================================
 * APP/API/AI/CHAT/ROUTE.TS ÔÇö AI Chat API Endpoint
 * =============================================================================
 *
 * Handles POST requests from the ChatPanel. This is the bridge between
 * the frontend and the AI orchestrator.
 *
 * FLOW:
 * 1. Parse the request body (message, project, history)
 * 2. Load the materials library
 * 3. Send to the AI orchestrator (Gemini/OpenAI)
 * 4. Validate any returned operations
 * 5. Return the AI's message + validated operations
 *
 * SECURITY:
 * - API keys are server-side only (never exposed to client)
 * - All operations are validated before being returned
 * - Rate limiting should be added in production
 * =============================================================================
 */

import { NextRequest, NextResponse } from 'next/server';
import { sendChatToAI } from '@/lib/ai/orchestrator';
import { validateOperation } from '@/lib/psg/validator';
import type { AIChatRequest, Material, PSGOperation } from '@/types';
import materialsJson from '@/data/materials.json';

export async function POST(request: NextRequest) {
    try {
        const body: AIChatRequest = await request.json();
        const { message, project, history } = body;

        if (!message?.trim()) {
            return NextResponse.json(
                { message: 'Please provide a message.', operations: [] },
                { status: 400 }
            );
        }

        // Load materials library (JSON is keyed by material ID)
        const materials: Record<string, Material> = {};
        for (const [id, mat] of Object.entries(materialsJson)) {
            materials[id] = mat as unknown as Material;
        }

        // Send to AI orchestrator
        const aiResponse = await sendChatToAI(
            { message, project, history: history || [] },
            materials
        );

        return NextResponse.json({
            message: aiResponse.message,
            operations: aiResponse.operations,
            warnings: aiResponse.warnings || [],
            suggestions: aiResponse.suggestions || [],
        });
    } catch (error) {
        console.error('[API /ai/chat] Error:', error);
        const errMsg = error instanceof Error ? error.message : 'Unknown error';
        return NextResponse.json(
            {
                message: `An error occurred: ${errMsg}`,
                operations: [],
                warnings: [{ severity: 'warning', message: errMsg }],
            },
            { status: 500 }
        );
    }
}

import { NextRequest, NextResponse } from 'next/server';
import { processImageTo3D } from '@/lib/ai/vision';
import type { ImageTo3DRequest } from '@/types';

export async function POST(request: NextRequest) {
    try {
        const body: ImageTo3DRequest = await request.json();
        const { image_data, reference_measurement, project } = body;

        if (!image_data) {
            return NextResponse.json(
                { message: 'Please provide an image.', operations: [] },
                { status: 400 }
            );
        }

        if (!reference_measurement?.trim()) {
            return NextResponse.json(
                { message: 'Please provide a reference measurement to scale the 3D model properly.', operations: [] },
                { status: 400 }
            );
        }

        // Send to vision AI
        const aiResponse = await processImageTo3D(body);

        return NextResponse.json({
            message: aiResponse.message,
            operations: aiResponse.operations,
            warnings: aiResponse.warnings || [],
        });
    } catch (error) {
        console.error('[API /ai/image-to-3d] Error:', error);
        const errMsg = error instanceof Error ? error.message : 'Unknown error';
        return NextResponse.json(
            {
                message: `An error occurred: ${errMsg}`,
                operations: [],
                warnings: [{ severity: 'warning', message: errMsg }],
            },
            { status: 500 }
        );
    }
}

/**
 * =============================================================================
 * APP/LAYOUT.TSX ÔÇö Root Layout
 * =============================================================================
 *
 * The root layout wraps every page. It:
 * - Sets up the HTML metadata (title, description, viewport)
 * - Loads the Inter font from Google Fonts
 * - Imports global CSS
 * - Provides the <html> and <body> structure
 *
 * WHY NOT USE CONTEXT PROVIDERS HERE?
 * Zustand doesn't need a Provider (unlike Redux). This keeps
 * the layout clean and simple. The store is just imported directly.
 * =============================================================================
 */

import type { Metadata } from 'next';
import './globals.css';

export const metadata: Metadata = {
  title: 'AI House Designer ÔÇö Design Your Dream Home in 3D',
  description:
    'Describe your dream family home and watch AI build it in 3D. Walk through every room, adjust walls with sliders, analyze thermal efficiency, and export professional architect plans.',
  keywords: ['house design', 'AI architect', '3D house', 'building plans', 'home design', 'parametric design'],
  openGraph: {
    title: 'AI House Designer',
    description: 'Design your dream home with AI. 3D walk-through, real materials, budget tracking, and professional building plans.',
    type: 'website',
  },
};

export default function RootLayout({
  children,
}: Readonly<{
  children: React.ReactNode;
}>) {
  return (
    <html lang="en">
      <head>
        <link
          rel="stylesheet"
          href="https://fonts.googleapis.com/css2?family=Inter:wght@300;400;500;600;700;800&display=swap"
        />
      </head>
      <body>{children}</body>
    </html>
  );
}

/**
 * =============================================================================
 * COMPONENTS/CHAT/CHAT-PANEL.TSX ÔÇö AI Chat Interface (Multi-Agent)
 * =============================================================================
 *
 * UPGRADE v3 ÔÇö Shows multi-agent pipeline status
 *
 * The chat panel where users interact with the AI architect.
 * Now shows which phase of the multi-agent pipeline is running:
 * - ­ƒºá Coordinator analyzing...
 * - ÔÜí Workers executing...
 * - ­ƒöì Checker reviewing...
 * - ­ƒöº Fixer correcting...
 * =============================================================================
 */

'use client';

import React, { useState, useRef, useEffect, useCallback } from 'react';
import { useDesignStore } from '@/store/useDesignStore';
import type { ChatMessage } from '@/types';
import { prepareProjectContext, generateASCIIFloorPlan } from '@/lib/ai/context';

// =============================================================================
// SUGGESTION CHIPS
// =============================================================================

const SUGGESTIONS = [
    'Add a first floor',
    'Make the living room 2m wider',
    'Add a window to the north wall',
    'Change the roof to a flat roof',
    'Add a balcony to the master bedroom',
    'Replace all brick with stone',
];

// =============================================================================
// MESSAGE BUBBLE
// =============================================================================

function MessageBubble({ msg, onRevert, showRevert }: { msg: ChatMessage, onRevert?: (id: string) => void, showRevert?: boolean }) {
    const isUser = msg.role === 'user';

    return (
        <div className={`chat-message ${isUser ? 'chat-message-user' : 'chat-message-ai'}`}>
            <div className="chat-message-header">
                <span className="chat-message-role">
                    {isUser ? '­ƒæñ You' : '­ƒÅù´©Å Architect AI'}
                </span>
                <span className="chat-message-time">
                    {new Date(msg.timestamp).toLocaleTimeString([], {
                        hour: '2-digit',
                        minute: '2-digit',
                    })}
                </span>
            </div>
            <p className="chat-message-content" style={{ whiteSpace: 'pre-wrap' }}>{msg.content}</p>
            {/* Operation badges ÔÇö show when AI made edits */}
            {msg.operations && msg.operations.length > 0 && (
                <div className="chat-operations">
                    <span className="chat-op-count">
                        {msg.operations.length} change{msg.operations.length !== 1 ? 's' : ''} applied
                    </span>
                    {msg.operations.map((op, i) => (
                        <span key={i} className="chat-op-badge">
                            {op.type.replace(/_/g, ' ')}
                        </span>
                    ))}
                </div>
            )}
            {isUser && showRevert && onRevert && (
                <button
                    onClick={() => onRevert(msg.id)}
                    title="Revert the house back to how it was when you sent this message"
                    style={{ fontSize: '0.75em', padding: '4px 8px', marginTop: '8px', background: 'var(--bg-secondary)', border: '1px solid var(--border)', borderRadius: '4px', cursor: 'pointer', display: 'flex', alignItems: 'center', gap: '4px', width: 'fit-content' }}
                >
                    Ôå®´©Å Go back
                </button>
            )}
        </div>
    );
}

// =============================================================================
// PIPELINE STATUS INDICATOR
// =============================================================================

function PipelineStatus() {
    const phases = [
        { emoji: '­ƒºá', label: 'Coordinator analyzing' },
        { emoji: 'ÔÜí', label: 'Workers executing' },
        { emoji: '­ƒöì', label: 'Checker reviewing' },
        { emoji: '­ƒöº', label: 'Fixer correcting' },
    ];

    const [currentPhase, setCurrentPhase] = useState(0);

    useEffect(() => {
        // Cycle through phases to show activity
        const interval = setInterval(() => {
            setCurrentPhase((prev) => Math.min(prev + 1, phases.length - 1));
        }, 4000);
        return () => clearInterval(interval);
    }, []);

    return (
        <div className="chat-message chat-message-ai">
            <div className="chat-pipeline-status">
                {phases.map((phase, i) => (
                    <div
                        key={i}
                        className={`pipeline-phase ${i < currentPhase ? 'pipeline-phase-done' :
                            i === currentPhase ? 'pipeline-phase-active' :
                                'pipeline-phase-pending'
                            }`}
                    >
                        <span className="pipeline-emoji">{phase.emoji}</span>
                        <span className="pipeline-label">{phase.label}</span>
                        {i === currentPhase && (
                            <span className="pipeline-dots">
                                <span className="chat-thinking-dot" />
                                <span className="chat-thinking-dot" />
                                <span className="chat-thinking-dot" />
                            </span>
                        )}
                        {i < currentPhase && <span className="pipeline-check">Ô£ô</span>}
                    </div>
                ))}
            </div>
        </div>
    );
}

// =============================================================================
// MAIN CHAT PANEL
// =============================================================================

export default function ChatPanel() {
    const [input, setInput] = useState('');
    const chatMessages = useDesignStore((s) => s.chatMessages);
    const addChatMessage = useDesignStore((s) => s.addChatMessage);
    const isAIThinking = useDesignStore((s) => s.isAIThinking);
    const setAIThinking = useDesignStore((s) => s.setAIThinking);
    const project = useDesignStore((s) => s.project);
    const applyOp = useDesignStore((s) => s.applyOp);
    const revertToMessage = useDesignStore((s) => s.revertToMessage);
    const messagesEndRef = useRef<HTMLDivElement>(null);

    // Auto-scroll to bottom on new messages
    useEffect(() => {
        messagesEndRef.current?.scrollIntoView({ behavior: 'smooth' });
    }, [chatMessages.length, isAIThinking]);

    const sendMessage = useCallback(async (text: string) => {
        if (!text.trim() || isAIThinking) return;

        // Deep clone current project state as a snapshot before AI makes changes
        const projectSnapshot = JSON.parse(JSON.stringify(project));

        // Add user message
        const userMsg: ChatMessage = {
            id: `msg_${Date.now()}`,
            role: 'user',
            content: text.trim(),
            timestamp: new Date().toISOString(),
            snapshot: projectSnapshot,
        };
        addChatMessage(userMsg);
        setInput('');
        setAIThinking(true);

        try {
            const response = await fetch('/api/ai/chat', {
                method: 'POST',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify({
                    message: text.trim(),
                    project,
                    history: chatMessages,
                }),
            });

            const data = await response.json();

            // Ô£à Apply AI operations to the 3D scene one-by-one so a single
            // bad op (e.g. hallucinated node ID) doesn't crash the whole batch.
            const allOps: typeof data.operations = data.operations || [];
            let successCount = 0;
            let failCount = 0;

            for (const op of allOps) {
                try {
                    const result = applyOp(op);
                    if (result.success) {
                        successCount++;
                    } else {
                        failCount++;
                        console.warn('[ChatPanel] Op failed validation:', op.type, op.target_id, result.errors);
                    }
                } catch (opErr) {
                    failCount++;
                    console.warn('[ChatPanel] Op threw at runtime:', op.type, op.target_id, opErr);
                }
            }

            if (allOps.length > 0) {
                console.log(`[ChatPanel] Applied ${successCount}/${allOps.length} operations (${failCount} failed)`);
            }

            const aiMsg: ChatMessage = {
                id: `msg_${Date.now()}_ai`,
                role: 'assistant',
                content: data.message || 'I processed your request.',
                timestamp: new Date().toISOString(),
                operations: allOps,
            };
            addChatMessage(aiMsg);
        } catch {
            const errMsg: ChatMessage = {
                id: `msg_${Date.now()}_err`,
                role: 'assistant',
                content: 'Sorry, I couldn\'t process that request. The AI backend may not be connected yet.',
                timestamp: new Date().toISOString(),
            };
            addChatMessage(errMsg);
        } finally {
            setAIThinking(false);
        }
    }, [input, isAIThinking, project, chatMessages, addChatMessage, setAIThinking, applyOp]);

    const handleSubmit = (e: React.FormEvent) => {
        e.preventDefault();
        sendMessage(input);
    };

    const handleKeyDown = (e: React.KeyboardEvent) => {
        if (e.key === 'Enter' && !e.shiftKey) {
            e.preventDefault();
            sendMessage(input);
        }
    };

    const handleDownloadSpecs = () => {
        const fullSpecs = prepareProjectContext(project);
        const asciiPlan = generateASCIIFloorPlan(project);

        const content = `// ASCII FLOOR PLAN\n${asciiPlan}\n\n// EXACT JSON SPECS SENT TO AI\n${fullSpecs}`;
        const blob = new Blob([content], { type: 'text/plain' });
        const url = URL.createObjectURL(blob);
        const a = document.createElement('a');
        a.href = url;
        a.download = `debug_ai_specs_${Date.now()}.txt`;
        document.body.appendChild(a);
        a.click();
        document.body.removeChild(a);
        URL.revokeObjectURL(url);
    };

    return (
        <div className="chat-panel">
            {/* Chat Header */}
            <div className="chat-header">
                <div>
                    <h3>­ƒÅù´©Å AI Architect <span style={{ fontSize: '0.65em', opacity: 0.6 }}>multi-agent</span></h3>
                    <button
                        onClick={handleDownloadSpecs}
                        style={{ fontSize: '0.7em', marginTop: '4px', background: 'var(--accent)', color: 'white', padding: '2px 6px', borderRadius: '4px', border: 'none', cursor: 'pointer' }}
                    >
                        Ôåô Download Debug Specs
                    </button>
                </div>
                <span className="chat-status">
                    {isAIThinking ? 'ÔÅ│ Processing...' : '­ƒƒó Ready'}
                </span>
            </div>

            {/* Messages Area */}
            <div className="chat-messages">
                {chatMessages.length === 0 && (
                    <div className="chat-welcome">
                        <p className="chat-welcome-title">Hello! ­ƒæï</p>
                        <p className="chat-welcome-text">
                            I&apos;m your AI architect team. Describe what you&apos;d like to change
                            about the house, and my multi-agent team will analyze, execute,
                            and verify the modifications.
                        </p>
                        <div className="chat-suggestions">
                            {SUGGESTIONS.map((s) => (
                                <button
                                    key={s}
                                    className="chat-suggestion-btn"
                                    onClick={() => sendMessage(s)}
                                >
                                    {s}
                                </button>
                            ))}
                        </div>
                    </div>
                )}

                {chatMessages.map((msg, index) => (
                    <MessageBubble
                        key={msg.id}
                        msg={msg}
                        onRevert={revertToMessage}
                        showRevert={!!msg.snapshot && index < chatMessages.length - 1}
                    />
                ))}

                {isAIThinking && <PipelineStatus />}

                <div ref={messagesEndRef} />
            </div>

            {/* Input Area */}
            <form className="chat-input-form" onSubmit={handleSubmit}>
                <textarea
                    className="chat-input"
                    value={input}
                    onChange={(e) => setInput(e.target.value)}
                    onKeyDown={handleKeyDown}
                    placeholder="Describe what you'd like to change..."
                    rows={2}
                    disabled={isAIThinking}
                />
                <button
                    type="submit"
                    className="chat-send-btn"
                    disabled={!input.trim() || isAIThinking}
                >
                    Send ÔåÆ
                </button>
            </form>
        </div>
    );
}

/**
 * =============================================================================
 * COMPONENTS/THREE/PSG-RENDERER.TSX ÔÇö Renders PSG Nodes as Architecturally
 *                                     Correct 3D Meshes
 * =============================================================================
 *
 * RENDERING STRATEGY:
 *
 *  WALLS:
 *   - Built with buildWallWithOpenings() ÔåÆ ExtrudeGeometry with holes
 *   - Corner resolution via resolveWallCorners() ÔåÆ no blind overlaps
 *   - Each wall is a SINGLE mesh (not box + separate window mesh)
 *
 *  WINDOWS:
 *   - buildWindowGroup() ÔåÆ frame (4 solid members) + glass pane
 *   - Positioned exactly at the opening in the parent wall
 *   - No separate "hole" mesh needed ÔÇö the wall has the hole already
 *
 *  DOORS:
 *   - buildDoorGroup() ÔåÆ frame (3 members) + door leaf
 *   - Door leaf sits in the closed position flush with interior wall face
 *
 *  ALL OTHER TYPES (Roof, Stairs, Slab, etc.):
 *   - Use getGeometryForNode() from compiler.ts (unchanged)
 *
 * PERFORMANCE:
 *  - Geometry is memoized by node.id + node.version
 *  - Material is cached by material_id
 *  - Each node is a separate mesh for raycasting/selection
 * =============================================================================
 */

'use client';

import React, { useMemo } from 'react';
import * as THREE from 'three';
import { ThreeEvent } from '@react-three/fiber';
import { useDesignStore } from '@/store/useDesignStore';
import {
    buildWallWithOpenings,
    buildWindowGroup,
    buildDoorGroup,
    resolveWallCorners,
    resolveWallPosition,
} from '@/lib/psg/geometry';
import { getGeometryForNode, compileMaterial, compileGlassMaterial } from '@/lib/psg/compiler';
import materialsDatabase from '@/data/materials.json';
import type { PSGNode, PSGProject, Material } from '@/types';

// =============================================================================
// MATERIAL CACHE
// =============================================================================

const materialCache = new Map<string, THREE.MeshStandardMaterial>();
const glassMaterial = compileGlassMaterial();

function getMaterial(materialId: string, opacity: number): THREE.Material {
    if (opacity < 1 || materialId.includes('glass')) return glassMaterial;
    if (materialCache.has(materialId)) return materialCache.get(materialId)!;
    const matDef = (materialsDatabase as Record<string, Material>)[materialId];
    if (matDef) {
        const m = compileMaterial(matDef);
        materialCache.set(materialId, m);
        return m;
    }
    const fallback = new THREE.MeshStandardMaterial({ color: '#888888', roughness: 0.8, metalness: 0.1, side: THREE.DoubleSide });
    materialCache.set(materialId, fallback);
    return fallback;
}

// =============================================================================
// HIGHLIGHT MATERIALS
// =============================================================================

const SELECTION_EMISSIVE = new THREE.Color(0x2266ff);
const HOVER_EMISSIVE = new THREE.Color(0x115599);

// =============================================================================
// NODE TYPES THAT RENDER GEOMETRY
// =============================================================================

const RENDERABLE_TYPES = new Set([
    'Wall', 'Window', 'Door', 'Roof', 'Stairs', 'Slab',
    'Foundation', 'Column', 'Beam', 'Partition',
    'Balcony', 'Garage', 'Chimney', 'Custom',
]);

// Openings are rendered AS PART OF their parent wall group ÔÇö skip standalone rendering
const OPENING_TYPES = new Set(['Window', 'Door']);

// =============================================================================
// WALL MESH ÔÇö with carved openings (no corner correction needed ÔÇö
//             templates use through+between joint strategy)
// =============================================================================

interface WallMeshProps {
    node: PSGNode;
    isSelected: boolean;
    isHovered: boolean;
    allNodes: Record<string, PSGNode>;
    isSystemVision: boolean;
    forcedOpacity?: number;
}

function WallMeshNode({ node, isSelected, isHovered, allNodes, isSystemVision, forcedOpacity }: WallMeshProps) {
    const selectNode = useDesignStore((s) => s.selectNode);
    const hoverNode = useDesignStore((s) => s.hoverNode);

    // Get corner-corrected wall data
    const { adjustedWidth, startInset, endInset } = useMemo(
        () => resolveWallCorners(node, allNodes),
        // eslint-disable-next-line react-hooks/exhaustive-deps
        [node.id, node.version, node.dimensions.x, node.dimensions.z, node.position.x, node.position.z, node.rotation.yaw]
    );

    // Create a "virtual" node with adjusted width for geometry building
    const adjustedNode = useMemo(() => ({
        ...node,
        dimensions: { ...node.dimensions, x: adjustedWidth },
    }), [node, adjustedWidth]);

    // Build wall geometry with openings
    const wallGeometry = useMemo(
        () => buildWallWithOpenings(adjustedNode, allNodes),
        // eslint-disable-next-line react-hooks/exhaustive-deps
        [node.id, node.version, adjustedWidth, node.dimensions.y, node.dimensions.z,
        node.children_ids.map(id => {
            const child = allNodes[id];
            return child ? `${child.version}_${child.position.x}_${child.position.z}_${child.position.y}` : '';
        }).join('|')]
    );

    const material = useMemo(
        () => getMaterial(node.material_id, node.opacity),
        [node.material_id, node.opacity]
    );

    // Corner-corrected center position
    const position = useMemo(
        () => resolveWallPosition(node, startInset, endInset),
        [node.position, startInset, endInset, node.rotation.yaw]
    );

    const rotation = useMemo<[number, number, number]>(() => [
        (node.rotation.pitch * Math.PI) / 180,
        (node.rotation.yaw * Math.PI) / 180,
        (node.rotation.roll * Math.PI) / 180,
    ], [node.rotation.yaw, node.rotation.pitch, node.rotation.roll]);

    const handleClick = (e: ThreeEvent<MouseEvent>) => { e.stopPropagation(); selectNode(node.id); };
    const handlePointerOver = (e: ThreeEvent<PointerEvent>) => { e.stopPropagation(); hoverNode(node.id); document.body.style.cursor = 'pointer'; };
    const handlePointerOut = () => { hoverNode(null); document.body.style.cursor = 'default'; };

    return (
        <group
            key={`${node.id}_${node.version}`}
            position={[position.x, position.y, position.z]}
            rotation={rotation}
        >
            {/* Wall solid with holes */}
            <mesh
                geometry={wallGeometry}
                onClick={handleClick}
                onPointerOver={handlePointerOver}
                onPointerOut={handlePointerOut}
                castShadow
                receiveShadow
            >
                {isSelected || isHovered ? (
                    <meshStandardMaterial
                        color={(material as THREE.MeshStandardMaterial).color || '#888888'}
                        roughness={0.7}
                        metalness={0.1}
                        side={THREE.DoubleSide}
                        emissive={isSelected ? SELECTION_EMISSIVE : HOVER_EMISSIVE}
                        emissiveIntensity={isSelected ? 0.3 : 0.15}
                        transparent={isSystemVision || node.opacity < 1}
                        opacity={isSystemVision ? 0.3 : node.opacity}
                    />
                ) : (
                    <primitive
                        object={material}
                        attach="material"
                        transparent={isSystemVision || node.opacity < 1 || forcedOpacity !== undefined}
                        opacity={forcedOpacity !== undefined ? forcedOpacity : (isSystemVision ? 0.3 : node.opacity)}
                    />
                )}
            </mesh>

            {/* Window + Door groups rendered here, positioned relative to wall center */}
            {node.children_ids.map(childId => {
                const child = allNodes[childId];
                if (!child || !OPENING_TYPES.has(child.type)) return null;
                return (
                    <OpeningGroup
                        key={`${childId}_${child.version}`}
                        node={child}
                        parentWall={node}
                        parentPosition={position}
                        allNodes={allNodes}
                        forcedOpacity={forcedOpacity}
                    />
                );
            })}
        </group>
    );
}

// =============================================================================
// OPENING GROUP (Window / Door)
// =============================================================================

interface OpeningGroupProps {
    node: PSGNode;
    parentWall: PSGNode;
    parentPosition: { x: number; y: number; z: number };
    allNodes: Record<string, PSGNode>;
    forcedOpacity?: number;
}

function OpeningGroup({ node, parentWall, parentPosition, allNodes, forcedOpacity }: OpeningGroupProps) {
    const selectNode = useDesignStore((s) => s.selectNode);
    const hoverNode = useDesignStore((s) => s.hoverNode);
    const selection = useDesignStore((s) => s.selection);
    const isSelected = selection.selected_node_id === node.id;
    const isHovered = selection.hovered_node_id === node.id;

    const wallThickness = parentWall.dimensions.z;

    // Build the 3D group (frame + glass / frame + leaf)
    const group = useMemo(() => {
        return node.type === 'Window'
            ? buildWindowGroup(node, wallThickness)
            : buildDoorGroup(node, wallThickness);
    }, [node, wallThickness]);

    // Local position within wall: the opening lives at its world position,
    // but we need to express it RELATIVE to the parent wall group
    const localPos = useMemo(() => {
        const yaw = Math.round(parentWall.rotation.yaw) % 180;
        const isNS = (yaw === 90 || yaw === -90);
        // Position relative to the SHIFTED wall center
        const wx = isNS ? (node.position.z - parentPosition.z) : (node.position.x - parentPosition.x);
        const wy = node.position.y - parentPosition.y;
        return { x: wx, y: wy, z: 0 };
    }, [node.position, parentPosition, parentWall.rotation.yaw]);

    const handleClick = (e: ThreeEvent<MouseEvent>) => { e.stopPropagation(); selectNode(node.id); };
    const handlePointerOver = (e: ThreeEvent<PointerEvent>) => { e.stopPropagation(); hoverNode(node.id); document.body.style.cursor = 'pointer'; };
    const handlePointerOut = () => { hoverNode(null); document.body.style.cursor = 'default'; };

    return (
        <group
            key={`${node.id}_${node.version}`}
            position={[localPos.x, localPos.y, localPos.z]}
            onClick={handleClick}
            onPointerOver={handlePointerOver}
            onPointerOut={handlePointerOut}
        >
            {useMemo(() => group.children.map((child, i) => {
                const mesh = child as THREE.Mesh;
                const mat = mesh.material as THREE.Material;
                let renderMat: THREE.Material = mat;

                if (isSelected || isHovered) {
                    renderMat = mat.clone();
                    if (renderMat instanceof THREE.MeshStandardMaterial) {
                        renderMat.emissive = isSelected ? SELECTION_EMISSIVE : HOVER_EMISSIVE;
                        renderMat.emissiveIntensity = isSelected ? 0.2 : 0.1;
                    }
                }

                return (
                    <mesh
                        key={`${node.id}_frame_${i}`}
                        geometry={mesh.geometry}
                        position={mesh.position}
                        castShadow
                        receiveShadow
                    >
                        <primitive
                            object={renderMat}
                            attach="material"
                            transparent={forcedOpacity !== undefined || renderMat.transparent}
                            opacity={forcedOpacity !== undefined ? forcedOpacity : renderMat.opacity}
                        />
                    </mesh>
                );
            }), [group.children, isSelected, isHovered, node.id, forcedOpacity])}
        </group>
    );
}

// =============================================================================
// GENERIC NODE MESH (Roof, Stairs, Slab, Column, Beam, Foundation, ...)
// =============================================================================

interface GenericMeshProps {
    node: PSGNode;
    isSelected: boolean;
    isHovered: boolean;
    isSystemVision: boolean;
    forcedOpacity?: number;
}

function GenericNodeMesh({ node, isSelected, isHovered, isSystemVision, forcedOpacity }: GenericMeshProps) {
    const selectNode = useDesignStore((s) => s.selectNode);
    const hoverNode = useDesignStore((s) => s.hoverNode);

    const geometryOrGroup = useMemo(
        () => getGeometryForNode(node),
        // eslint-disable-next-line react-hooks/exhaustive-deps
        [node.type, node.dimensions.x, node.dimensions.y, node.dimensions.z, node.version, node.roof_style, node.stair_style]
    );

    const material = useMemo(() => getMaterial(node.material_id, node.opacity), [node.material_id, node.opacity]);

    const rotation = useMemo<[number, number, number]>(() => [
        (node.rotation.pitch * Math.PI) / 180,
        (node.rotation.yaw * Math.PI) / 180,
        (node.rotation.roll * Math.PI) / 180,
    ], [node.rotation.yaw, node.rotation.pitch, node.rotation.roll]);

    const handleClick = (e: ThreeEvent<MouseEvent>) => { e.stopPropagation(); selectNode(node.id); };
    const handlePointerOver = (e: ThreeEvent<PointerEvent>) => { e.stopPropagation(); hoverNode(node.id); document.body.style.cursor = 'pointer'; };
    const handlePointerOut = () => { hoverNode(null); document.body.style.cursor = 'default'; };

    if (geometryOrGroup instanceof THREE.Group) {
        return (
            <group
                key={`${node.id}_${node.version}`}
                position={[node.position.x, node.position.y, node.position.z]}
                rotation={rotation}
            >
                {geometryOrGroup.children.map((child, i) => {
                    const mesh = child as THREE.Mesh;
                    return (
                        <mesh
                            key={`${node.id}_step_${i}`}
                            geometry={mesh.geometry}
                            position={mesh.position}
                            onClick={handleClick}
                            onPointerOver={handlePointerOver}
                            onPointerOut={handlePointerOut}
                            castShadow
                            receiveShadow
                        >
                            <meshStandardMaterial
                                color={(material as THREE.MeshStandardMaterial).color}
                                roughness={0.6}
                                metalness={0.1}
                                side={THREE.DoubleSide}
                                emissive={isSelected ? SELECTION_EMISSIVE : isHovered ? HOVER_EMISSIVE : undefined}
                                emissiveIntensity={isSelected ? 0.3 : isHovered ? 0.15 : 0}
                                transparent={isSystemVision || node.opacity < 1 || forcedOpacity !== undefined}
                                opacity={forcedOpacity !== undefined ? forcedOpacity : (isSystemVision ? 0.2 : node.opacity)}
                            />
                        </mesh>
                    );
                })}
            </group>
        );
    }

    return (
        <mesh
            key={`${node.id}_${node.version}_${node.material_id}`}
            geometry={geometryOrGroup}
            position={[node.position.x, node.position.y, node.position.z]}
            rotation={rotation}
            onClick={handleClick}
            onPointerOver={handlePointerOver}
            onPointerOut={handlePointerOut}
            castShadow
            receiveShadow
        >
            <meshStandardMaterial
                color={(material as THREE.MeshStandardMaterial).color || '#888888'}
                roughness={0.7}
                metalness={0.1}
                side={THREE.DoubleSide}
                transparent={isSystemVision || node.opacity < 1 || forcedOpacity !== undefined}
                opacity={forcedOpacity !== undefined ? forcedOpacity : (isSystemVision ? 0.2 : node.opacity)}
                emissive={isSelected ? SELECTION_EMISSIVE : isHovered ? HOVER_EMISSIVE : undefined}
                emissiveIntensity={isSelected ? 0.3 : isHovered ? 0.15 : 0}
            />
        </mesh>
    );
}

// =============================================================================
// PSG RENDERER ÔÇö iterates all renderable nodes
// =============================================================================

export default function PSGRenderer() {
    const project = useDesignStore((s) => s.project);
    const selection = useDesignStore((s) => s.selection);
    const selectNode = useDesignStore((s) => s.selectNode);
    const visibleLayers = useDesignStore((s) => s.visibleLayers);
    const viewMode = useDesignStore((s) => s.viewMode);
    const activeFloorId = useDesignStore((s) => s.activeFloorId);

    const isSystemVision = visibleLayers.has('electrical') || visibleLayers.has('plumbing') || visibleLayers.has('thermal') || visibleLayers.has('hvac');

    const allNodes = project.nodes;

    // Helper to find which floor a node belongs to
    const nodeFloorMap = useMemo(() => {
        const map = new Map<string, string>();
        const findFloor = (node: PSGNode): string | null => {
            if (node.type === 'Floor') return node.id;
            if (!node.parent_id) return null;
            const parent = allNodes[node.parent_id];
            if (!parent) return null;
            return findFloor(parent);
        };

        Object.values(allNodes).forEach((node) => {
            const floorId = findFloor(node);
            if (floorId) map.set(node.id, floorId);
        });
        return map;
    }, [allNodes]);

    // Floors sorted by height
    const sortedFloors = useMemo(() =>
        Object.values(allNodes)
            .filter(n => n.type === 'Floor')
            .sort((a, b) => a.position.y - b.position.y),
        [allNodes]
    );

    const activeFloorIndex = activeFloorId ? sortedFloors.findIndex(f => f.id === activeFloorId) : -1;

    // Nodes that are the "top-level" renderable structural elements
    // Windows and Doors are rendered INSIDE their parent wall group
    const wallsAndPartitions = useMemo(
        () => Object.values(allNodes).filter((n) => n.type === 'Wall' || n.type === 'Partition'),
        [allNodes]
    );

    const otherNodes = useMemo(
        () => Object.values(allNodes).filter(
            (n) => RENDERABLE_TYPES.has(n.type) && !OPENING_TYPES.has(n.type) && n.type !== 'Wall' && n.type !== 'Partition'
        ),
        [allNodes]
    );

    const isNodeVisible = (node: PSGNode): boolean => {
        if (viewMode !== 'top_down') return true;

        if (activeFloorId) {
            const floorId = nodeFloorMap.get(node.id);
            // Non-floor elements like Foundation are visible
            if (!floorId) {
                if (node.type === 'Roof') return false;
                // If it's foundation and we are looking at ground floor, let's keep it visible or hide?
                // For exact mathematical plan, just show the current floor. We can hide foundation unless it's the ground floor?
                // Actually, if it has no floor, let's just make it visible, maybe it's terrain. 
                // But let's hide roof anyway.
                return true;
            }

            const floorIndex = sortedFloors.findIndex(f => f.id === floorId);

            // Exactly show ONLY the active floor items
            if (floorIndex !== activeFloorIndex) return false;

            // Even if on active floor (e.g., roof on top floor), hide the roof to see the plan
            if (node.type === 'Roof') return false;

            return true;
        }

        // Top down mode but NO active floor selected:
        // Hide roofs to see all floors inside
        if (node.type === 'Roof') return false;

        return true;
    };

    const getForcedOpacity = (node: PSGNode) => {
        return undefined; // We are hiding entirely instead of changing opacity
    };

    return (
        <group
            onClick={(e) => {
                if (e.object.type === 'Mesh' && !e.object.userData.psgNodeId) {
                    selectNode(null);
                }
            }}
        >
            {/* Walls with carved openings */}
            {wallsAndPartitions.filter(isNodeVisible).map((node) => (
                <WallMeshNode
                    key={node.id}
                    node={node}
                    isSelected={selection.selected_node_id === node.id}
                    isHovered={selection.hovered_node_id === node.id}
                    allNodes={allNodes}
                    isSystemVision={isSystemVision}
                    forcedOpacity={getForcedOpacity(node)}
                />
            ))}

            {/* All other structural + architectural nodes */}
            {otherNodes.filter(isNodeVisible).map((node) => (
                <GenericNodeMesh
                    key={node.id}
                    node={node}
                    isSelected={selection.selected_node_id === node.id}
                    isHovered={selection.hovered_node_id === node.id}
                    isSystemVision={isSystemVision}
                    forcedOpacity={getForcedOpacity(node)}
                />
            ))}
        </group>
    );
}

/**
 * =============================================================================
 * COMPONENTS/THREE/WALKTHROUGH-CONTROLS.TSX ÔÇö First-Person Viewport Controls
 * =============================================================================
 * 
 * Provides a 'walk-through' experience similar to a 3D game.
 * Uses PointerLockControls for mouse-look and keyboard for movement.
 * 
 * FEATURES:
 * 1. WASD + Arrow keys for horizontal movement
 * 2. Mouse-look (Pointer Lock)
 * 3. Constant Eye-Level (Locks Y to walk_height)
 * 4. Movement smoothing (Damping)
 * 5. Simple Boundary Collision
 * =============================================================================
 */

'use client';

import React, { useEffect, useRef, useState } from 'react';
import { useThree, useFrame } from '@react-three/fiber';
import { PointerLockControls, Html } from '@react-three/drei';
import * as THREE from 'three';
import { useDesignStore } from '@/store/useDesignStore';

/**
 * Key mapping for movement
 */
const KEY_MAP: Record<string, string> = {
    KeyW: 'forward',
    ArrowUp: 'forward',
    KeyS: 'backward',
    ArrowDown: 'backward',
    KeyA: 'left',
    ArrowLeft: 'left',
    KeyD: 'right',
    ArrowRight: 'right',
};

export default function WalkthroughControls() {
    const { camera } = useThree();
    const cameraState = useDesignStore((s) => s.camera);
    const viewMode = useDesignStore((s) => s.viewMode);

    // Movement state
    const moveState = useRef({
        forward: false,
        backward: false,
        left: false,
        right: false,
        velocity: new THREE.Vector3(),
        direction: new THREE.Vector3(),
    });

    const [isLocked, setIsLocked] = useState(false);
    const controlsRef = useRef<any>(null);

    // Manual lock handler with safety check
    const handleLock = () => {
        if (!controlsRef.current || isLocked) return;

        // Some browsers require a fresh user gesture and might throw if 
        // a previous request is still pending.
        try {
            controlsRef.current.lock();
        } catch (err) {
            console.warn('WalkthroughControls: Pointer lock request failed', err);
        }
    };

    // Setup keyboard listeners
    useEffect(() => {
        if (viewMode !== 'walkthrough') return;

        const handleKeyDown = (e: KeyboardEvent) => {
            const action = KEY_MAP[e.code];
            if (action === 'forward' || action === 'backward' || action === 'left' || action === 'right') {
                moveState.current[action] = true;
            }
        };

        const handleKeyUp = (e: KeyboardEvent) => {
            const action = KEY_MAP[e.code];
            if (action === 'forward' || action === 'backward' || action === 'left' || action === 'right') {
                moveState.current[action] = false;
            }
        };

        window.addEventListener('keydown', handleKeyDown);
        window.addEventListener('keyup', handleKeyUp);

        return () => {
            window.removeEventListener('keydown', handleKeyDown);
            window.removeEventListener('keyup', handleKeyUp);
        };
    }, [viewMode]);

    // Handle frame-based movement
    useFrame((state, delta) => {
        if (viewMode !== 'walkthrough' || !isLocked) return;

        const { forward, backward, left, right, velocity, direction } = moveState.current;

        // 1. Calculate direction vector from inputs
        direction.z = Number(forward) - Number(backward);
        direction.x = Number(right) - Number(left);
        direction.normalize();

        // 2. Apply damping (friction) to velocity
        velocity.x -= velocity.x * 10.0 * delta;
        velocity.z -= velocity.z * 10.0 * delta;

        // 3. Apply acceleration
        const speed = 40.0 * cameraState.walk_speed;
        if (forward || backward) velocity.z -= direction.z * speed * delta;
        if (left || right) velocity.x -= direction.x * speed * delta;

        // 4. Apply velocity to camera position (local space)
        // We move the camera relative to its current rotation, but only on the XZ plane
        state.camera.translateX(-velocity.x * delta);
        state.camera.translateZ(velocity.z * delta);

        // 5. Lock Y to eye level (Ground height + walk_height)
        // TODO: Phase 4: Use Raycasting to find ground height (for stairs/hills)
        state.camera.position.y = cameraState.walk_height;

        // 6. Simple Boundary Collision (don't wander too far from 0,0)
        const LIMIT = 100;
        state.camera.position.x = THREE.MathUtils.clamp(state.camera.position.x, -LIMIT, LIMIT);
        state.camera.position.z = THREE.MathUtils.clamp(state.camera.position.z, -LIMIT, LIMIT);
    });

    if (viewMode !== 'walkthrough') return null;

    return (
        <>
            <PointerLockControls
                ref={controlsRef}
                onLock={() => setIsLocked(true)}
                onUnlock={() => setIsLocked(false)}
            />

            {/* Visual Indicator/Instruction when not locked */}
            {!isLocked && (
                <Html fullscreen>
                    <div
                        className="walkthrough-overlay"
                        onClick={(e) => {
                            e.stopPropagation();
                            handleLock();
                        }}
                    >
                        <div className="walkthrough-hint">
                            <p className="walkthrough-hint-title">Walkthrough Mode</p>
                            <p>Click anywhere to start</p>
                            <div className="walkthrough-keys">
                                <span>W A S D</span> ÔÇö Move
                                <br />
                                <span>MOUSE</span> ÔÇö Look
                                <br />
                                <span>ESC</span> ÔÇö Exit
                            </div>
                        </div>
                    </div>
                </Html>
            )}
        </>
    );
}

/**
 * =============================================================================
 * COMPONENTS/UI/IMAGE-TO-3D-MODAL.TSX 
 * =============================================================================
 *
 * Modal allowing the user to upload a house image and a reference measurement
 * to auto-generate a 3D structural model.
 * =============================================================================
 */

import React, { useState, useEffect, useRef } from 'react';
import { createPortal } from 'react-dom';
import { useDesignStore } from '@/store/useDesignStore';
import type { PSGOperation } from '@/types';

interface Props {
    isOpen: boolean;
    onClose: () => void;
}

export default function ImageTo3DModal({ isOpen, onClose }: Props) {
    const [file, setFile] = useState<File | null>(null);
    const [previewUrl, setPreviewUrl] = useState<string | null>(null);
    const [base64Data, setBase64Data] = useState<string | null>(null);
    const [referenceMeasurement, setReferenceMeasurement] = useState<string>('');
    const [isGenerating, setIsGenerating] = useState<boolean>(false);
    const [error, setError] = useState<string | null>(null);

    const fileInputRef = useRef<HTMLInputElement>(null);
    const project = useDesignStore((s) => s.project);
    const applyOp = useDesignStore((s) => s.applyOp);
    const [mounted, setMounted] = useState(false);

    useEffect(() => {
        setMounted(true);
    }, []);

    if (!isOpen || !mounted) return null;

    const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
        const selectedFile = e.target.files?.[0];
        if (!selectedFile) return;

        setFile(selectedFile);

        // Create preview URL
        const objectUrl = URL.createObjectURL(selectedFile);
        setPreviewUrl(objectUrl);

        // Convert to base64 for API
        const reader = new FileReader();
        reader.onloadend = () => {
            setBase64Data(reader.result as string);
        };
        reader.readAsDataURL(selectedFile);
        setError(null);
    };

    const handleGenerate = async () => {
        if (!base64Data) {
            setError('Please select an image first.');
            return;
        }
        if (!referenceMeasurement.trim()) {
            setError('Please provide a reference measurement (e.g. "The front door is 2m high").');
            return;
        }

        setIsGenerating(true);
        setError(null);

        try {
            const response = await fetch('/api/ai/image-to-3d', {
                method: 'POST',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify({
                    image_data: base64Data,
                    reference_measurement: referenceMeasurement,
                    project,
                    budget: project.budget.total_budget,
                    currency: project.budget.currency
                }),
            });

            const data = await response.json();

            if (!response.ok) {
                throw new Error(data.message || 'Failed to generate 3D model.');
            }

            const ops: PSGOperation[] = data.operations || [];

            if (ops.length === 0) {
                // Throwing the message will display it in the modal's error banner
                throw new Error(data.message || 'The AI could not identify any 3D structure in this image, or an error occurred.');
            }

            // Apply operations sequentially
            let successCount = 0;
            for (const op of ops) {
                const result = applyOp(op);
                if (result.success) successCount++;
            }

            console.log(`[ImageTo3D] Applied ${successCount}/${ops.length} operations.`);

            // Close modal on success
            onClose();

        } catch (err) {
            setError(err instanceof Error ? err.message : String(err));
        } finally {
            setIsGenerating(false);
        }
    };

    return createPortal(
        <div className="modal-overlay" onClick={onClose}>
            <div className="modal-content" onClick={(e) => e.stopPropagation()} style={{ maxWidth: 500 }}>
                <div className="modal-header">
                    <h2>­ƒô© Photo to 3D Model</h2>
                    <button className="modal-close" onClick={onClose}>Ô£ò</button>
                </div>

                <div className="modal-body">
                    <p style={{ color: 'var(--text-secondary)', marginBottom: 'var(--space-4)' }}>
                        Upload a photo of a house and the AI will analyze its architecture and translate it directly into your 3D canvas.
                    </p>

                    {/* Image Upload Area */}
                    <div
                        className="upload-area"
                        onClick={() => fileInputRef.current?.click()}
                        style={{
                            border: '2px dashed var(--border-color)',
                            borderRadius: 'var(--border-radius)',
                            padding: 'var(--space-6)',
                            textAlign: 'center',
                            cursor: 'pointer',
                            marginBottom: 'var(--space-4)',
                            background: 'var(--bg-input)',
                            transition: 'all var(--transition-fast)'
                        }}
                    >
                        {previewUrl ? (
                            <img
                                src={previewUrl}
                                alt="Preview"
                                style={{ maxHeight: '200px', maxWidth: '100%', objectFit: 'contain', borderRadius: '4px' }}
                            />
                        ) : (
                            <div style={{ color: 'var(--text-muted)' }}>
                                <div style={{ fontSize: '2rem', marginBottom: 'var(--space-2)' }}>­ƒôÑ</div>
                                Click to select or drag & drop an image here.
                            </div>
                        )}
                        <input
                            type="file"
                            ref={fileInputRef}
                            style={{ display: 'none' }}
                            accept="image/jpeg,image/png,image/webp"
                            onChange={handleFileChange}
                        />
                    </div>

                    {/* Reference Measurement */}
                    <div style={{ marginBottom: 'var(--space-4)' }}>
                        <label style={{ display: 'block', marginBottom: 'var(--space-2)', color: 'var(--text-primary)', fontWeight: 'bold' }}>
                            Reference Measurement (Required)
                        </label>
                        <p style={{ color: 'var(--text-muted)', fontSize: 'var(--text-sm)', marginBottom: 'var(--space-2)' }}>
                            To get perfect metric scale, please tell the AI the real-world size of one element in the photo.
                        </p>
                        <input
                            className="chat-input"
                            style={{ width: '100%' }}
                            value={referenceMeasurement}
                            onChange={(e) => setReferenceMeasurement(e.target.value)}
                            placeholder="e.g. 'The green front door is 2.1m high'"
                            disabled={isGenerating}
                        />
                    </div>

                    {error && (
                        <div style={{ padding: 'var(--space-3)', background: 'rgba(255,68,85,0.1)', color: 'var(--accent-danger)', borderRadius: 'var(--border-radius-sm)', marginBottom: 'var(--space-4)', fontSize: 'var(--text-sm)' }}>
                            {error}
                        </div>
                    )}

                </div>

                <div className="modal-footer" style={{ display: 'flex', justifyContent: 'flex-end', gap: 'var(--space-3)', padding: 'var(--space-4)', borderTop: '1px solid var(--border-color)' }}>
                    <button className="toolbar-btn" onClick={onClose} disabled={isGenerating}>
                        Cancel
                    </button>
                    <button
                        className="export-btn"
                        onClick={handleGenerate}
                        disabled={!base64Data || !referenceMeasurement.trim() || isGenerating}
                        style={{ display: 'flex', alignItems: 'center', gap: '8px' }}
                    >
                        {isGenerating ? (
                            <>
                                <span className="chat-thinking-dot" style={{ animation: 'dots 1.5s infinite step-start 0s' }} /> Processing...
                            </>
                        ) : 'Generate 3D'}
                    </button>
                </div>
            </div>
        </div>,
        document.body
    );
}

/**
 * =============================================================================
 * LIB/AI/ORCHESTRATOR.TS ÔÇö Multi-Agent Agentic Architecture
 * =============================================================================
 *
 * UPGRADE v3 ÔÇö Full multi-agent rewrite
 *
 * ARCHITECTURE:
 * ÔöîÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÉ
 * Ôöé  User Request                                                   Ôöé
 * Ôöé       Ôöé                                                         Ôöé
 * Ôöé       Ôû╝                                                         Ôöé
 * Ôöé  ÔöîÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÉ                                       Ôöé
 * Ôöé  Ôöé  COORDINATOR AGENT   Ôöé  Understands the request in 3D       Ôöé
 * Ôöé  Ôöé  (Planning Phase)    Ôöé  context. Reads current building     Ôöé
 * Ôöé  Ôöé                      Ôöé  state. Plans sub-tasks.             Ôöé
