): Promise<WorkerResult> {
    const mistakeDescriptions = mistakes
        .map((m, i) => `${i + 1}. [Node: ${m.node_id}] ${m.description}\n   Expected: ${m.expected}\n   Actual: ${m.actual}\n   Fix: ${m.fix_description}`)
