### ASCII FLOOR PLAN
\`\`\`
${asciiPlan}
\`\`\`

### FULL NODE DATA
\`\`\`json
${buildingSpecs}
\`\`\`

## MISTAKES TO FIX
${mistakeDescriptions}

Fix each mistake above using tool calls. Show your reasoning.`,
        },
    ];

    const result = await callProviderWithTools(config, messages);

