/**
 * Compiles the geometry type string from a PSGNode type.
 * Used by React components to determine which geometry generator to use.
 *
 * This is a lookup table rather than a switch statement because it's
 * called frequently during re-renders and lookup tables are faster.
 */
export const GEOMETRY_COMPILERS: Record<
    string,
    (node: PSGNode) => THREE.BufferGeometry | THREE.Group
> = {
    Wall: compileWallGeometry,
    Partition: compilePartitionGeometry,
    Slab: compileSlabGeometry,
    Foundation: compileFoundationGeometry,
    Window: compileWindowGeometry,
    Door: compileDoorGeometry,
    Roof: compileRoofGeometry,
    Stairs: compileStairsGeometry,
    Column: compileColumnGeometry,
    Beam: compileBeamGeometry,
    Balcony: compileBalconyGeometry,
    Custom: compileCustomGeometry,
};

/**
 * Gets the appropriate geometry for a PSG node.
 * Falls back to a small cube if the node type is unknown.
 */
export function getGeometryForNode(
    node: PSGNode
): THREE.BufferGeometry | THREE.Group {
    const compiler = GEOMETRY_COMPILERS[node.type];
    if (compiler) {
        return compiler(node);
    }
    // Fallback: 1m cube placeholder
    return new THREE.BoxGeometry(1, 1, 1);
}

/**
 * =============================================================================
 * LIB/PSG/COST-CALCULATOR.TS ÔÇö Material Cost & Budget Engine
 * =============================================================================
 *
 * Calculates the total material cost of a house by:
 * 1. Computing the VOLUME of each node (from its dimensions)
 * 2. Looking up the material's density (kg/m┬│) and price (Ôé¼/kg)
 * 3. Multiplying: volume ├ù density ├ù price_per_kg = cost
 *
 * WHY VOLUME-BASED COSTING?
 * Unlike area-based estimates (which only work for flat surfaces),
 * volume-based costing works for ALL geometry types:
 * - Walls: width ├ù height ├ù thickness = volume
 * - Slabs: width ├ù thickness ├ù depth = volume
 * - Stairs: sum of step volumes
 * - Roofs: calculated from pitch and dimensions
 *
 * This gives ACCURATE material quantities, not just surface area
 * estimates. The user can see exactly how many kg of each material
 * they need and what it costs.
 *
 * BUDGET WARNINGS:
 * After every edit, the cost is recalculated. If the total exceeds
 * the user's budget or crosses the warning threshold, the UI shows
 * a warning. The AI also receives the budget state in its context
 * so it can proactively suggest cost savings.
 * =============================================================================
 */

import type {
    PSGProject,
    PSGNode,
    Material,
    MaterialSummaryItem,
    BudgetConfig,
} from '@/types';

// =============================================================================
// VOLUME CALCULATION
// =============================================================================

/**
 * Calculates the volume of a PSG node in cubic meters.
 *
 * SPECIAL CASES:
 * - Windows/Doors: subtract opening volume from parent wall
 * - Stairs: sum of individual step volumes
 * - Gable roofs: triangular prism volume
 * - Rooms/Houses/Floors: 0 volume (they're containers, not physical)
 *
 * @param node - The PSG node to calculate volume for
 * @returns Volume in m┬│
 */
export function calculateNodeVolume(node: PSGNode): number {
    const { x: width, y: height, z: depth } = node.dimensions;

    switch (node.type) {
        case 'Wall':
        case 'Slab':
        case 'Partition':
        case 'Column':
        case 'Beam':
        case 'Foundation':
            // Simple box volume
            return width * height * depth;

        case 'Window':
        case 'Door':
            // Openings have negative volume (subtracted from wall)
            // Their own material volume is just the frame/glass
            // For cost purposes, we calculate the frame volume
            return calculateFrameVolume(node);

        case 'Stairs':
            return calculateStairsVolume(node);

        case 'Roof':
            return calculateRoofVolume(node);

        case 'House':
        case 'Floor':
        case 'Room':
            // Container nodes have no physical volume
            return 0;

        default:
            // Fallback: simple box
            return width * height * depth;
    }
}

/**
 * Calculates the frame volume for windows and doors.
 *
 * ASSUMPTIONS:
 * - Frame width: 60mm (0.06m)
 * - Frame depth: 50mm (0.05m) ÔÇö matches the node's z dimension
 * - Glass thickness: negligible for cost purposes
 */
function calculateFrameVolume(node: PSGNode): number {
    const openW = node.opening_width || node.dimensions.x;
    const openH = node.opening_height || node.dimensions.y;
    const frameWidth = 0.06; // 60mm frame
    const frameDepth = node.dimensions.z || 0.05;

    // Frame is a rectangular ring
    const outerArea = (openW + 2 * frameWidth) * (openH + 2 * frameWidth);
    const innerArea = openW * openH;
    const frameArea = outerArea - innerArea;

    return frameArea * frameDepth;
}

/**
 * Calculates the total volume of all steps in a staircase.
 */
function calculateStairsVolume(node: PSGNode): number {
    const riserHeight = node.stair_riser_height || 0.18;
    const treadDepth = node.stair_tread_depth || 0.28;
    const stairWidth = node.dimensions.x;
    const totalHeight = node.dimensions.y;

    const numSteps = Math.ceil(totalHeight / riserHeight);
    const stepVolume = stairWidth * riserHeight * treadDepth;

    return numSteps * stepVolume;
}

/**
 * Calculates roof volume based on style and pitch.
 *
 * For gable roofs: volume = width ├ù depth ├ù ridgeHeight / 2
 * (triangular prism formula)
 */
function calculateRoofVolume(node: PSGNode): number {
    const { x: width, y: thickness, z: depth } = node.dimensions;

    if (node.roof_style === 'gable' && node.roof_pitch_degrees) {
        const pitchRad = (node.roof_pitch_degrees * Math.PI) / 180;
        const ridgeHeight = Math.tan(pitchRad) * (depth / 2);
        // Triangular prism + the thickness of the roofing material
        const prismVolume = (width * depth * ridgeHeight) / 2;
        const shellVolume = width * depth * thickness; // Approximate shell
        return shellVolume; // We cost the roofing material, not the air inside
    }

    // Flat roof: simple slab
    return width * thickness * depth;
}

// =============================================================================
// COST CALCULATION
// =============================================================================

/**
 * Calculates the cost of a single node based on its material.
 *
 * FORMULA:
 * volume (m┬│) ├ù density (kg/m┬│) = mass (kg)
 * mass (kg) ├ù price_per_kg = cost
 *
 * @returns Cost in the project's currency
 */
export function calculateNodeCost(
    node: PSGNode,
    material: Material | undefined
): { volume_m3: number; weight_kg: number; cost: number } {
    if (!material) {
        return { volume_m3: 0, weight_kg: 0, cost: 0 };
    }

    const volume = calculateNodeVolume(node);
    const weight = volume * material.density_kg_m3;
    const cost = weight * material.price_per_kg;

    return {
        volume_m3: Math.round(volume * 1000) / 1000, // Round to 3 decimal places
        weight_kg: Math.round(weight * 10) / 10,      // Round to 1 decimal
        cost: Math.round(cost * 100) / 100,            // Round to cents
    };
}

// =============================================================================
// PROJECT-WIDE COST SUMMARY
// =============================================================================

/**
 * Calculates the complete material cost summary for the entire project.
 *
 * RETURNS:
 * - Per-material breakdown (grouped by material_id)
 * - Total cost
 * - Updated budget config with spent/remaining
 *
 * HOW IT WORKS:
 * 1. Iterates over all nodes in the project
 * 2. Looks up each node's material from the materials library
 * 3. Calculates volume ÔåÆ mass ÔåÆ cost for each node
 * 4. Groups results by material for the summary table
 * 5. Sums everything for the total
 *
 * @param project - The current PSG project
 * @param materials - The materials library (Record<material_id, Material>)
 */
export function calculateProjectCost(
    project: PSGProject,
    materials: Record<string, Material>
): {
    items: MaterialSummaryItem[];
    totalCost: number;
    updatedBudget: BudgetConfig;
} {
    // Group costs by material_id
    const materialGroups: Record<
        string,
        {
            material: Material;
            total_volume: number;
            total_weight: number;
            total_cost: number;
            node_ids: string[];
        }
    > = {};

    // Process each node
    for (const [nodeId, node] of Object.entries(project.nodes)) {
        // Skip container nodes (House, Floor, Room ÔÇö they have no material)
        if (!node.material_id || node.material_id === '') continue;

        const material = materials[node.material_id];
        if (!material) continue;

        const { volume_m3, weight_kg, cost } = calculateNodeCost(node, material);

        if (!materialGroups[node.material_id]) {
            materialGroups[node.material_id] = {
                material,
                total_volume: 0,
                total_weight: 0,
                total_cost: 0,
                node_ids: [],
            };
        }

        materialGroups[node.material_id].total_volume += volume_m3;
        materialGroups[node.material_id].total_weight += weight_kg;
        materialGroups[node.material_id].total_cost += cost;
        materialGroups[node.material_id].node_ids.push(nodeId);
    }

    // Convert to MaterialSummaryItem array
    const items: MaterialSummaryItem[] = Object.values(materialGroups).map(
        (group) => ({
            material: group.material,
            volume_m3: Math.round(group.total_volume * 1000) / 1000,
            weight_kg: Math.round(group.total_weight * 10) / 10,
            cost: Math.round(group.total_cost * 100) / 100,
            used_in: group.node_ids,
        })
    );

    // Sort by cost (most expensive first)
    items.sort((a, b) => b.cost - a.cost);

    // Calculate total
    const totalCost = items.reduce((sum, item) => sum + item.cost, 0);

    // Update budget
    const updatedBudget: BudgetConfig = {
        ...project.budget,
        spent: Math.round(totalCost * 100) / 100,
        remaining: Math.round((project.budget.total_budget - totalCost) * 100) / 100,
    };

    return { items, totalCost, updatedBudget };
}

/**
 * Estimates the cost impact of changing a single node's material.
 *
 * Used by the AI to provide instant cost feedback before applying
 * a material swap, e.g.:
 * "Changing to granite would increase cost by Ôé¼2,400 (+8.3%)"
 *
 * @param node - The node being changed
 * @param currentMaterial - Its current material
 * @param newMaterial - The proposed new material
 * @returns Cost difference (positive = more expensive)
 */
export function estimateMaterialChangeCost(
    node: PSGNode,
    currentMaterial: Material,
    newMaterial: Material
): {
    currentCost: number;
    newCost: number;
    difference: number;
    percentChange: number;
} {
    const currentResult = calculateNodeCost(node, currentMaterial);
    const newResult = calculateNodeCost(node, newMaterial);

    const difference = newResult.cost - currentResult.cost;
    const percentChange =
        currentResult.cost > 0
            ? (difference / currentResult.cost) * 100
            : 0;

    return {
        currentCost: currentResult.cost,
        newCost: newResult.cost,
        difference: Math.round(difference * 100) / 100,
        percentChange: Math.round(percentChange * 10) / 10,
    };
}

/**
 * =============================================================================
 * LIB/PSG/GEOMETRY.TS ÔÇö Precision Architectural Geometry Engine
 * =============================================================================
 *
 * This module creates ARCHITECTURALLY CORRECT Three.js geometry:
 *
 *  WALLS:
 *   - Each wall is a solid box with HOLES cut out where windows/doors sit
 *   - Holes are computed from child Window/Door nodes
 *   - The wall is built as a custom BufferGeometry using Shape + ShapeGeometry
 *   - Corner intersections are handled by the renderer (no blind overlaps)
 *
 *  WINDOWS:
 *   - A frame made of 4 rectangular solid members (top, bottom, left, right)
 *   - A thin glass pane set in the middle of the frame
 *   - The frame depth matches the wall thickness
 *
 *  DOORS:
 *   - A frame (3 solid members: top + 2 sides) matching wall thickness
 *   - A door leaf (flat panel, slightly proud of frame) in the closed position
 *   - An arc "swing" indicator mesh for floor plans
 *
 *  COORDINATE SYSTEM (same as compiler.ts):
 *   X = East, Y = Up, Z = South
 *   All dimensions in METERS
 *
 * HOW WALL OPENINGS WORK:
 *  1. Query all child nodes of the wall that are Window or Door
 *  2. For each opening: compute its local [xMin, xMax, yMin, yMax] within 
 *     the wall's local X-Y plane (wall origin = bottom-left corner)
 *  3. Build a 2D Shape (THREE.Shape) of the wall face with rectangular holes
 *  4. Extrude the shape along Z by the wall thickness
 *  5. This gives a solid wall with perfectly carved rectangular openings
 * =============================================================================
 */

import * as THREE from 'three';
import type { PSGNode, PSGProject } from '@/types';

// =============================================================================
// CONSTANTS
// =============================================================================

/** Frame member width in meters (50mm) */
const FRAME_WIDTH = 0.05;
/** Glass pane thickness in meters (6mm double glaze approximation) */
const GLASS_THICKNESS = 0.012;

// =============================================================================
// WALL WITH OPENINGS
// =============================================================================

/**
 * Creates an architecturally correct wall mesh:
 * - A solid box with rectangular holes for every child Window/Door
 * - Wall face runs along the local X axis, height along Y, thickness along Z
 *
 * @param wall - The Wall PSGNode
 * @param allNodes - All nodes in the project (to find children)
 * @returns THREE.Group containing the wall geometry mesh (+ optionally glass panes)
 */
export function buildWallWithOpenings(
    wall: PSGNode,
    allNodes: Record<string, PSGNode>
): THREE.BufferGeometry {
    const W = wall.dimensions.x;  // Wall width
    const H = wall.dimensions.y;  // Wall height
    const T = wall.dimensions.z;  // Wall thickness

    // Collect all Window and Door children
    const openings = wall.children_ids
        .map((id) => allNodes[id])
        .filter((n) => n && (n.type === 'Window' || n.type === 'Door'));

    if (openings.length === 0) {
        // Simple box ÔÇö no openings
        return new THREE.BoxGeometry(W, H, T);
    }

    // Build the 2D face shape of the wall (XY plane)
    // Wall local origin: center of the wall face
    // Shape coords: x Ôêê [-W/2, W/2], y Ôêê [-H/2, H/2]
    const wallShape = new THREE.Shape();
    const hw = W / 2;
    const hh = H / 2;

    wallShape.moveTo(-hw, -hh);
    wallShape.lineTo(hw, -hh);
    wallShape.lineTo(hw, hh);
    wallShape.lineTo(-hw, hh);
    wallShape.closePath();

    // Punch a hole for each opening
    for (const opening of openings) {
        const ow = opening.opening_width ?? opening.dimensions.x;
        const oh = opening.opening_height ?? opening.dimensions.y;

        // opening.position is in WORLD space; we need LOCAL space relative to wall center
        // Wall is centered at its position, so local X = world X - wall.position.x (for 0┬░ yaw walls)
        // For rotated walls (90┬░ yaw) we must swap X/Z
        const localX = getOpeningLocalX(wall, opening);
        const localY = opening.position.y - wall.position.y; // opening Y center in local wall frame

        const ox0 = localX - ow / 2;
        const ox1 = localX + ow / 2;
        const oy0 = localY - oh / 2;
        const oy1 = localY + oh / 2;

        // Clamp to wall bounds
        const cx0 = Math.max(-hw, ox0);
        const cx1 = Math.min(hw, ox1);
        const cy0 = Math.max(-hh, oy0);
        const cy1 = Math.min(hh, oy1);

        if (cx1 > cx0 && cy1 > cy0) {
            const hole = new THREE.Path();
            // Winding order for holes must be CW (opposite of main shape which is CCW)
            // CCW: (min,min) -> (max,min) -> (max,max) -> (min,max)
            // CW: (min,min) -> (min,max) -> (max,max) -> (max,min)
            hole.moveTo(cx0, cy0);
            hole.lineTo(cx0, cy1);
            hole.lineTo(cx1, cy1);
            hole.lineTo(cx1, cy0);
            hole.closePath();
            wallShape.holes.push(hole);
        }
    }

    // Extrude the 2D shape along Z to get the 3D wall with holes
    const extrudeSettings: THREE.ExtrudeGeometryOptions = {
        depth: T,
        bevelEnabled: false,
    };

    const geometry = new THREE.ExtrudeGeometry(wallShape, extrudeSettings);
    // Center the geometry along Z (ExtrudeGeometry starts at Z=0, goes to Z=depth)
    geometry.translate(0, 0, -T / 2);
    geometry.computeVertexNormals();

    return geometry;
}

/**
 * Computes the local X offset of an opening within its parent wall.
 *
 * For a wall aligned East-West (yaw=0┬░): local X = opening.position.x - wall.position.x
 * For a wall aligned North-South (yaw=90┬░): local X = opening.position.z - wall.position.z
 */
function getOpeningLocalX(wall: PSGNode, opening: PSGNode): number {
    const yaw = Math.abs(wall.rotation.yaw % 180);
    if (yaw === 0) {
        return opening.position.x - wall.position.x;
    } else {
        return opening.position.z - wall.position.z;
    }
}

// =============================================================================
// WINDOW FRAME GEOMETRY
// =============================================================================

/**
 * Builds a THREE.Group containing:
 *  1. The 4 frame members (solid box sections around the perimeter)
 *  2. The glass pane (thin transparent box)
 *
 * All geometry is centered at the origin (0,0,0) matching the window node's position.
 *
 * @param window - The Window PSGNode
 * @param wallThickness - Thickness of the parent wall (frame depth = wall thickness)
 * @returns THREE.Group
 */
export function buildWindowGroup(window: PSGNode, wallThickness: number = 0.25): THREE.Group {
    const group = new THREE.Group();
    const W = window.opening_width ?? window.dimensions.x;
    const H = window.opening_height ?? window.dimensions.y;
    const T = wallThickness; // Frame depth = wall thickness
    const fw = FRAME_WIDTH;

    // Material for frame (painted aluminum / timber ÔÇö will be overridden by renderer)
    const frameMat = new THREE.MeshStandardMaterial({
        color: 0xeeeeee,
        roughness: 0.4,
        metalness: 0.3,
        side: THREE.DoubleSide,
    });

    // Material for glass
    const glassMat = new THREE.MeshPhysicalMaterial({
        color: 0x88ccff,
        transparent: true,
        opacity: 0.25,
        roughness: 0.0,
        metalness: 0.0,
        transmission: 0.95,
        side: THREE.DoubleSide,
    });

    // ÔöÇÔöÇ Frame members ÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇ
    // Top rail
    addFrameMember(group, W, fw, T, 0, H / 2 - fw / 2, 0, frameMat);
    // Bottom rail
    addFrameMember(group, W, fw, T, 0, -H / 2 + fw / 2, 0, frameMat);
    // Left stile (vertical)
    addFrameMember(group, fw, H - 2 * fw, T, -W / 2 + fw / 2, 0, 0, frameMat);
    // Right stile (vertical)
    addFrameMember(group, fw, H - 2 * fw, T, W / 2 - fw / 2, 0, 0, frameMat);

    // ÔöÇÔöÇ Glass pane ÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇ
    const glassW = W - 2 * fw;
    const glassH = H - 2 * fw;
    const glassGeom = new THREE.BoxGeometry(glassW, glassH, GLASS_THICKNESS);
    const glassMesh = new THREE.Mesh(glassGeom, glassMat);
    group.add(glassMesh);

    return group;
}

/** Helper: adds a box-shaped frame member to a group */
function addFrameMember(
    group: THREE.Group,
    w: number, h: number, d: number,
    x: number, y: number, z: number,
    material: THREE.Material
): void {
    const geom = new THREE.BoxGeometry(w, h, d);
    const mesh = new THREE.Mesh(geom, material);
    mesh.position.set(x, y, z);
    group.add(mesh);
}

// =============================================================================
// DOOR FRAME + LEAF GEOMETRY
// =============================================================================

/**
 * Builds a THREE.Group containing:
 *  1. Door frame (three solid members: top + left + right jamb)
 *  2. Door leaf (flat panel, in closed position ÔÇö flush with wall face)
 *
 * @param door - The Door PSGNode
 * @param wallThickness - Thickness of the parent wall
 * @returns THREE.Group
 */
export function buildDoorGroup(door: PSGNode, wallThickness: number = 0.25): THREE.Group {
    const group = new THREE.Group();
    const W = door.opening_width ?? door.dimensions.x;
    const H = door.opening_height ?? door.dimensions.y;
    const T = wallThickness;
    const fw = FRAME_WIDTH;

    // Frame material (painted wood or aluminum)
    const frameMat = new THREE.MeshStandardMaterial({
        color: 0xc8a87a,  // Light timber color
        roughness: 0.7,
        metalness: 0.0,
        side: THREE.DoubleSide,
    });

    // Door leaf material (matches door material_id ÔÇö will be overridden by renderer)
    const doorMat = new THREE.MeshStandardMaterial({
        color: 0xa0784a,  // Darker timber
        roughness: 0.6,
        metalness: 0.0,
        side: THREE.DoubleSide,
    });

    // ÔöÇÔöÇ Frame ÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇ
    // Top head (horizontal)
    addFrameMember(group, W + 2 * fw, fw, T, 0, H / 2 + fw / 2, 0, frameMat);
    // Left jamb (vertical, from floor to underside of head)
    addFrameMember(group, fw, H, T, -W / 2 - fw / 2, 0, 0, frameMat);
    // Right jamb
    addFrameMember(group, fw, H, T, W / 2 + fw / 2, 0, 0, frameMat);

    // ÔöÇÔöÇ Door leaf ÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇ
    // 40mm thick solid door panel
    const leafThickness = 0.04;
    const leafGeom = new THREE.BoxGeometry(W - 0.01, H - 0.01, leafThickness);
    const leaf = new THREE.Mesh(leafGeom, doorMat);
    // Position leaf: slightly inside wall (towards the room interior side)
    leaf.position.set(0, 0, -(T / 2 - leafThickness / 2));
    group.add(leaf);

    return group;
}

// =============================================================================
// WALL CORNER CORRECTION
// =============================================================================

/**
 * Resolves how two perpendicular or angled walls meet at a corner to eliminate gaps.
 * Uses a precise "Source of Truth" geometry approach.
 *
 * STRATEGY:
 * 1. Calculate the precise endpoints of the wall centerline.
 * 2. Find any other wall whose centerline or face intersects this wall's endpoint.
 * 3. Shorten the "butt" wall by exactly the distance needed to stop at the face of the "through" wall.
 */
export function resolveWallCorners(
    wall: PSGNode,
    allNodes: Record<string, PSGNode>
): { adjustedWidth: number; startInset: number; endInset: number } {
    const W = wall.dimensions.x;
    const T = wall.dimensions.z;

    // Exact angle math
    const angle = (wall.rotation.yaw * Math.PI) / 180;
    const cosA = Math.cos(angle);
    const sinA = Math.sin(angle);

    // Half width
    const hw = W / 2;

    // Precise centerline endpoints
    const startX = wall.position.x - hw * cosA;
    const startZ = wall.position.z + hw * sinA;
    const endX = wall.position.x + hw * cosA;
    const endZ = wall.position.z - hw * sinA;

    let startInset = 0;
    let endInset = 0;

    // Tolerance for snapping (5cm is usually enough for precise architectural models)
    const TOLERANCE = 0.05;

    for (const other of Object.values(allNodes)) {
        if (other.id === wall.id) continue;
        if (other.type !== 'Wall' && other.type !== 'Partition') continue;

        const otherW = other.dimensions.x;
        const otherT = other.dimensions.z;
        const otherAngle = (other.rotation.yaw * Math.PI) / 180;
        const otherCos = Math.cos(otherAngle);
        const otherSin = Math.sin(otherAngle);

        // Is the other wall perpendicular? (roughly)
        const dot = Math.abs(cosA * otherCos - sinA * otherSin);
        const isPerp = dot < 0.1; // Nearly 90 degrees

        // We only butt-joint into perpendicular or nearly perpendicular walls
        if (!isPerp) continue;

        // Check if startPt or endPt of this wall is within the other wall's volume
        // To simplify: check distance from our endpoint to other wall's centerline
        const dxStart = startX - other.position.x;
        const dzStart = startZ - other.position.z;

        // Project onto other wall's axes
        const distAlongOther = Math.abs(dxStart * otherCos - dzStart * otherSin);
        const distAcrossOther = Math.abs(dxStart * otherSin + dzStart * otherCos);

        // If start point is within the "end region" of the other wall
        if (distAlongOther <= (otherW / 2 + TOLERANCE) && distAcrossOther <= (otherT / 2 + TOLERANCE)) {
            // Priority: larger-ID wall or specific tags could decide "through" vs "butt"
            // For now, if we are the one hitting the other wall's centerline, we butt.
            if (distAcrossOther < TOLERANCE) {
                startInset = Math.max(startInset, otherT / 2);
            }
        }

        const dxEnd = endX - other.position.x;
        const dzEnd = endZ - other.position.z;
        const distAlongOtherEnd = Math.abs(dxEnd * otherCos - dzEnd * otherSin);
        const distAcrossOtherEnd = Math.abs(dxEnd * otherSin + dzEnd * otherCos);

        if (distAlongOtherEnd <= (otherW / 2 + TOLERANCE) && distAcrossOtherEnd <= (otherT / 2 + TOLERANCE)) {
            if (distAcrossOtherEnd < TOLERANCE) {
                endInset = Math.max(endInset, otherT / 2);
            }
        }
    }

    return {
        adjustedWidth: Math.max(W - startInset - endInset, 0.01), // Min 1cm
        startInset,
        endInset
    };
}

/**
 * Computes adjusted position for walls that were inset to prevent gaps/overlaps.
 * Shifts the center along the wall's orientation vector.
 */
export function resolveWallPosition(
    wall: PSGNode,
    startInset: number,
    endInset: number
): { x: number; y: number; z: number } {
    const angle = (wall.rotation.yaw * Math.PI) / 180;
    const cosA = Math.cos(angle);
    const sinA = Math.sin(angle);

    // The shift balance: if we inset more at the end than the start,
    // the center moves towards the start.
    const shift = (endInset - startInset) / 2;

    return {
        x: wall.position.x - shift * cosA,
        y: wall.position.y,
        z: wall.position.z + shift * sinA,
    };
}

// =============================================================================
// PARENT WALL THICKNESS LOOKUP
// =============================================================================

/**
 * Given a Window or Door node, returns the thickness of its parent wall.
 * Falls back to 0.25m (250mm standard cavity wall) if parent not found.
 */
export function getParentWallThickness(
    node: PSGNode,
    allNodes: Record<string, PSGNode>
): number {
    if (!node.parent_id) return 0.25;
    const parent = allNodes[node.parent_id];
    if (!parent || (parent.type !== 'Wall' && parent.type !== 'Partition')) return 0.25;
    return parent.dimensions.z;
}

/**
 * =============================================================================
 * LIB/PSG/SCHEMA.TS ÔÇö PSG Schema Defaults & Factory Functions
 * =============================================================================
 *
 * This file provides factory functions to create properly initialized PSG nodes.
 * Instead of manually constructing PSGNode objects (which have 20+ fields),
 * you call createWall(), createRoom(), etc. to get a valid node with sensible
 * defaults.
 *
 * WHY FACTORY FUNCTIONS?
 * - Ensures every node has all required fields (no undefined errors at runtime)
 * - Provides sensible architectural defaults (2.7m wall height, 0.25m thickness)
 * - Generates unique IDs automatically
 * - Sets timestamps and version numbers
 * - The AI can also call these via tool functions to add new elements
 *
 * NAMING CONVENTION:
 * Node IDs follow the pattern: {type}_{room}_{direction}_{index}
 * Example: "wall_living_north_1", "window_bedroom_east_2"
 * This makes the PSG JSON human-readable when the LLM processes it.
 * =============================================================================
 */

import { v4 as uuidv4 } from 'uuid';
import type {
    PSGNode,
    PSGProject,
    PSGNodeType,
    Vec3,
    Rotation,
    StructuralTag,
    NodeConstraints,
    SystemConnections,
    ProjectSettings,
    BudgetConfig,
    Material,
} from '@/types';

// =============================================================================
// DEFAULT VALUES
// =============================================================================
// These defaults are based on standard European residential construction.
// They can be overridden per-project via ProjectSettings.

/** Default architectural dimensions in meters */
export const DEFAULTS = {
    WALL_HEIGHT: 2.7,        // Standard residential ceiling height
    WALL_THICKNESS: 0.25,    // 250mm cavity wall
    FLOOR_THICKNESS: 0.3,    // 300mm reinforced slab
    WINDOW_WIDTH: 1.2,       // Standard window
    WINDOW_HEIGHT: 1.4,
    WINDOW_SILL_HEIGHT: 0.9, // Height from floor to window bottom
    DOOR_WIDTH: 0.9,         // Standard interior door
    DOOR_HEIGHT: 2.1,
    GRID_SIZE: 0.1,          // 10cm grid snap
    ROOF_PITCH: 35,          // Degrees ÔÇö common for tile roofs
    ROOF_OVERHANG: 0.5,      // 500mm overhang
    STAIR_RISER: 0.18,       // 180mm riser height
    STAIR_TREAD: 0.28,       // 280mm tread depth
} as const;

// =============================================================================
// HELPER: Generate Timestamp
// =============================================================================

function now(): string {
    return new Date().toISOString();
}

// =============================================================================
// HELPER: Default Spatial Values
// =============================================================================

function defaultPosition(): Vec3 {
    return { x: 0, y: 0, z: 0 };
}

function defaultDimensions(): Vec3 {
    return { x: 1, y: 1, z: 1 };
}

function defaultRotation(): Rotation {
    return { yaw: 0, pitch: 0, roll: 0 };
}

function defaultConstraints(): NodeConstraints {
    return {
        fixed_position: false,
        connected_to: [],
    };
}

function defaultSystems(): SystemConnections {
    return {
        electrical: [],
        plumbing: [],
        hvac: [],
    };
}

// =============================================================================
// NODE FACTORY FUNCTIONS
// =============================================================================
// Each function creates a PSGNode with type-appropriate defaults.
// All spatial values are in meters.

/**
 * Creates the root House node.
 * Every PSG project has exactly ONE House node as the root.
 * All floors, rooms, and elements are descendants of this node.
 */
export function createHouseNode(name: string = 'New House'): PSGNode {
    return {
        id: `house_${uuidv4().slice(0, 8)}`,
        type: 'House',
        name,
        position: defaultPosition(),
        dimensions: defaultDimensions(), // House dimensions are computed from children
        rotation: defaultRotation(),
        material_id: '',                 // House node has no material
        opacity: 1,
        tags: [],
        constraints: { ...defaultConstraints(), fixed_position: true },
        systems: defaultSystems(),
        parent_id: null,
        children_ids: [],
        created_at: now(),
        modified_at: now(),
        version: 1,
    };
}

/**
 * Creates a Floor node (storey/level).
 * Contains Rooms, which in turn contain Walls.
 * Position.y determines the vertical offset (0 = ground floor).
 */
export function createFloorNode(
    parentId: string,
    level: number = 0, // 0 = ground, 1 = first floor, etc.
    name?: string
): PSGNode {
    return {
        id: `floor_${level}_${uuidv4().slice(0, 8)}`,
        type: 'Floor',
        name: name || `Floor ${level}`,
        position: { x: 0, y: level * DEFAULTS.WALL_HEIGHT, z: 0 },
        dimensions: { x: 0, y: DEFAULTS.FLOOR_THICKNESS, z: 0 }, // Computed from children
        rotation: defaultRotation(),
        material_id: 'mat_concrete_slab',
        opacity: 1,
        tags: ['load_bearing'],
        constraints: { ...defaultConstraints(), fixed_position: true },
        systems: defaultSystems(),
        parent_id: parentId,
        children_ids: [],
        created_at: now(),
        modified_at: now(),
        version: 1,
    };
}

/**
 * Creates a Room node.
 * Rooms are containers for walls ÔÇö they define a named space.
 * The room's position is relative to its floor.
 */
export function createRoomNode(
    parentId: string,
    name: string,
    position: Partial<Vec3> = {},
    dimensions: Partial<Vec3> = {},
    roomFunction?: string
): PSGNode {
    return {
        id: `room_${name.toLowerCase().replace(/\s+/g, '_')}_${uuidv4().slice(0, 8)}`,
        type: 'Room',
        name,
        position: { ...defaultPosition(), ...position },
        dimensions: { x: 4, y: DEFAULTS.WALL_HEIGHT, z: 5, ...dimensions },
        rotation: defaultRotation(),
        material_id: '',
        opacity: 1,
        tags: [],
        constraints: defaultConstraints(),
        systems: defaultSystems(),
        parent_id: parentId,
        children_ids: [],
        room_function: roomFunction,
        created_at: now(),
        modified_at: now(),
        version: 1,
    };
}

/**
 * Creates a Wall node.
 * Walls are the most common node type. They can be load-bearing or partitions.
 *
 * COORDINATE SYSTEM:
 * - x = width (horizontal span of the wall)
 * - y = height (floor to ceiling)
 * - z = thickness (depth of the wall construction)
 *
 * The wall's position is its CENTER point. A wall at position (4, 1.35, 0)
 * with dimensions (8, 2.7, 0.25) spans from x=0 to x=8, y=0 to y=2.7.
 */
export function createWallNode(
    parentId: string,
    name: string,
    position: Partial<Vec3> = {},
    width: number = 4,
    height: number = DEFAULTS.WALL_HEIGHT,
    thickness: number = DEFAULTS.WALL_THICKNESS,
    tags: StructuralTag[] = ['load_bearing', 'exterior']
): PSGNode {
    return {
        id: `wall_${name.toLowerCase().replace(/\s+/g, '_')}_${uuidv4().slice(0, 8)}`,
        type: 'Wall',
        name,
        position: { x: 0, y: height / 2, z: 0, ...position },
        dimensions: { x: width, y: height, z: thickness },
        rotation: defaultRotation(),
        material_id: 'mat_brick_red',
        opacity: 1,
        tags,
        constraints: {
            min_width: 0.5,
            min_height: 2.1,
            min_thickness: 0.1,
            connected_to: [],
        },
        systems: defaultSystems(),
        parent_id: parentId,
        children_ids: [],
        created_at: now(),
        modified_at: now(),
        version: 1,
    };
}

/**
 * Creates a Window node.
 * Windows are children of walls ÔÇö their position is relative to the wall.
 */
export function createWindowNode(
    parentWallId: string,
    name: string,
    position: Partial<Vec3> = {},
    width: number = DEFAULTS.WINDOW_WIDTH,
    height: number = DEFAULTS.WINDOW_HEIGHT
): PSGNode {
    return {
        id: `window_${uuidv4().slice(0, 8)}`,
        type: 'Window',
        name,
        position: { x: 0, y: DEFAULTS.WINDOW_SILL_HEIGHT + height / 2, z: 0, ...position },
        dimensions: { x: width, y: height, z: 0.05 }, // ~50mm frame depth
        rotation: defaultRotation(),
        material_id: 'mat_glass_double',
        opacity: 0.3,
        tags: [],
        constraints: {
            min_width: 0.4,
            max_width: 3.0,
            min_height: 0.4,
            max_height: 2.4,
            connected_to: [parentWallId],
        },
        systems: defaultSystems(),
        parent_id: parentWallId,
        children_ids: [],
        opening_width: width,
        opening_height: height,
        created_at: now(),
        modified_at: now(),
        version: 1,
    };
}

/**
 * Creates a Door node.
 * Like windows, doors are children of walls.
 */
export function createDoorNode(
    parentWallId: string,
    name: string,
    position: Partial<Vec3> = {},
    width: number = DEFAULTS.DOOR_WIDTH,
    height: number = DEFAULTS.DOOR_HEIGHT
): PSGNode {
    return {
        id: `door_${uuidv4().slice(0, 8)}`,
        type: 'Door',
        name,
        position: { x: 0, y: height / 2, z: 0, ...position },
        dimensions: { x: width, y: height, z: 0.05 },
        rotation: defaultRotation(),
        material_id: 'mat_wood_oak',
        opacity: 1,
        tags: [],
        constraints: {
            min_width: 0.7,
            max_width: 1.8,
            min_height: 1.9,
            max_height: 2.4,
            connected_to: [parentWallId],
        },
        systems: defaultSystems(),
        parent_id: parentWallId,
        children_ids: [],
        opening_width: width,
        opening_height: height,
        created_at: now(),
        modified_at: now(),
        version: 1,
    };
}

/**
 * Creates a Roof node.
 * The roof's geometry is determined by roof_style and roof_pitch_degrees.
 * The Three.js compiler uses these to generate the appropriate mesh.
 */
export function createRoofNode(
