/**
 * Creates a Beam node (horizontal structural spanning element).
 * Beams span between columns or walls, supporting floor loads above.
 * Dimensions: x = span length, y = depth (vertical), z = width.
 */
export function createBeamNode(
    parentId: string,
    name: string,
    position: Partial<Vec3> = {},
    span: number = 4,
    depth: number = 0.4,
    width: number = 0.25
): PSGNode {
    return {
        id: `beam_${uuidv4().slice(0, 8)}`,
        type: 'Beam',
        name,
        position: { x: 0, y: DEFAULTS.WALL_HEIGHT - depth / 2, z: 0, ...position },
        dimensions: { x: span, y: depth, z: width },
        rotation: defaultRotation(),
        material_id: 'mat_steel_beam',
        opacity: 1,
        tags: ['load_bearing'],
        constraints: {
            min_width: 1.0,      // Min span
            min_height: 0.15,    // Min depth
            min_thickness: 0.1,  // Min width
            connected_to: [],
        },
        systems: defaultSystems(),
        parent_id: parentId,
        children_ids: [],
        created_at: now(),
        modified_at: now(),
        version: 1,
    };
}

/**
 * Creates a Partition node (non-load-bearing internal wall).
 * Partitions are thinner than structural walls (100mm vs 250mm).
 * They can be freely moved/removed without structural concerns.
 */
export function createPartitionNode(
    parentId: string,
    name: string,
    position: Partial<Vec3> = {},
    width: number = 3,
    height: number = DEFAULTS.WALL_HEIGHT,
    thickness: number = 0.1
): PSGNode {
    return {
        id: `partition_${uuidv4().slice(0, 8)}`,
        type: 'Partition',
        name,
        position: { x: 0, y: height / 2, z: 0, ...position },
        dimensions: { x: width, y: height, z: thickness },
        rotation: defaultRotation(),
        material_id: 'mat_plasterboard',
        opacity: 1,
        tags: ['interior'],
        constraints: {
            min_width: 0.5,
            min_height: 2.1,
            min_thickness: 0.05,
            connected_to: [],
        },
        systems: defaultSystems(),
        parent_id: parentId,
        children_ids: [],
        created_at: now(),
        modified_at: now(),
        version: 1,
    };
}

// =============================================================================
// PROJECT FACTORY
// =============================================================================

/**
 * Creates a new empty PSGProject with sensible defaults.
 * This is the starting point before the AI generates the house.
 */
export function createEmptyProject(
    name: string = 'Untitled Project',
    budget: number = 200000,
    currency: string = 'EUR'
): PSGProject {
    const houseNode = createHouseNode(name);

    return {
        id: uuidv4(),
        name,
        description: '',
        created_at: now(),
        modified_at: now(),
        version: 1,
        root_node_id: houseNode.id,
        nodes: {
            [houseNode.id]: houseNode,
        },
        settings: createDefaultSettings(),
        budget: {
            total_budget: budget,
            spent: 0,
            remaining: budget,
            currency,
            warnings_enabled: true,
            warning_threshold: 90, // Warn at 90% spent
        },
    };
}

function createDefaultSettings(): ProjectSettings {
    return {
        unit: 'metric',
        grid_size: DEFAULTS.GRID_SIZE,
        default_wall_height: DEFAULTS.WALL_HEIGHT,
        default_wall_thickness: DEFAULTS.WALL_THICKNESS,
        locale: 'en-US',
        currency: 'EUR',
    };
}

/**
 * =============================================================================
 * LIB/PSG/TEMPLATES.TS ÔÇö Starter House Templates
 * =============================================================================
 *
 * Pre-built house templates for quick-start projects.
 *
 * WALL POSITIONING STRATEGY ÔÇö "THROUGH + BETWEEN" JOINTS:
 * ÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇ
 *  Problem: Walls have thickness (T=0.25m). A wall at z=0 occupies
 *           z = -T/2 to z = +T/2.  Two perpendicular walls both
 *           positioned at their grid-line centers leave a T├ùT gap.
 *
 *  Solution: Use "through" and "between" wall strategy:
 *
 *   ÔÇó HORIZONTAL walls (EW, yaw=0) are "THROUGH" walls:
 *     - Their center X is at the CENTER of the house width.
 *     - Their LENGTH extends to the OUTER faces of the corner walls.
 *     - A north wall for a 10m-wide house has length = 10m + T,
 *       centered at x = house_center. This FULLY covers both corners.
 *
 *   ÔÇó VERTICAL walls (NS, yaw=90) are "BETWEEN" walls:
 *     - Their length is the interior span BETWEEN the inner faces
 *       of the two horizontal walls they connect.
 *     - For a room that goes from z=0 to z=6 with horizontal walls
 *       at both ends (each T thick), the NS wall length =
 *       6 - T (the gap between inner faces).
 *     - The NS wall center Z = midpoint of the interior span.
 *
 *  Result: Every corner is a clean butt joint with no gaps, no overlaps.
 *
 * COORDINATE SYSTEM:
 * - X axis: East-West (positive = east)
 * - Y axis: Up-Down (positive = up, Y=0 is ground)
 * - Z axis: North-South (positive = south)
 * - All positions are CENTER points of nodes
 * - All dimensions are in meters
 * =============================================================================
 */

import type { PSGProject, PSGNode } from '@/types';
import {
    createHouseNode,
    createFloorNode,
    createRoomNode,
    createWallNode,
    createWindowNode,
    createDoorNode,
    createRoofNode,
    createStairsNode,
    createSlabNode,
    createFoundationNode,
    createPartitionNode,
    createEmptyProject,
    DEFAULTS,
} from './schema';

// =============================================================================
// HELPER: Add node to project and link to parent
// =============================================================================

function add(project: PSGProject, node: PSGNode): PSGNode {
    project.nodes[node.id] = node;
    if (node.parent_id && project.nodes[node.parent_id]) {
        project.nodes[node.parent_id].children_ids.push(node.id);
    }
    return node;
}

/**
 * Add a wall and set its rotation in one step.
 * Returns the wall node for chaining.
 */
function addWall(
    project: PSGProject,
    parentId: string,
    name: string,
    pos: { x: number; y: number; z: number },
    length: number,
    height: number,
    thickness: number,
    tags: PSGNode['tags'],
    yaw: number = 0
): PSGNode {
    const wall = add(project, createWallNode(parentId, name, pos, length, height, thickness, tags));
    if (yaw !== 0) {
        wall.rotation = { yaw, pitch: 0, roll: 0 };
    }
    return wall;
}

/**
 * Add a partition and set rotation in one step.
 */
function addPartition(
    project: PSGProject,
    parentId: string,
    name: string,
    pos: { x: number; y: number; z: number },
    length: number,
    height: number,
    thickness: number,
    yaw: number = 0
): PSGNode {
    const part = add(project, createPartitionNode(parentId, name, pos, length, height, thickness));
    if (yaw !== 0) {
        part.rotation = { yaw, pitch: 0, roll: 0 };
    }
    return part;
}

// =============================================================================
// TEMPLATE: Simple 3-Bedroom, Single Floor
// =============================================================================

/**
 * Creates a simple single-storey, 3-bedroom family home.
 *
 * LAYOUT ÔÇö 10m wide (X) ├ù 12m deep (Z), origin = northwest outer corner.
 *
 *     North (Z = 0)
 *     ÔöîÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÉ
 *     Ôöé         Living Room          Ôöé
 *     Ôöé         (10m ├ù 6m)           Ôöé  Z=0 to Z=6
 *     Ôö£ÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöñ
 *     Ôöé    Kitchen    Ôöé   Bathroom   Ôöé
 *     Ôöé   (5m ├ù 3m)  Ôöé  (5m ├ù 3m)   Ôöé  Z=6 to Z=9
 *     Ôö£ÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔö╝ÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöñ
 *     Ôöé   Bedroom 1   Ôöé  Bedroom 2  Ôöé
 *     Ôöé  (5m ├ù 3m)   Ôöé  (5m ├ù 3m)  Ôöé  Z=9 to Z=12
 *     ÔööÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔö┤ÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÿ
 *     South (Z = 12)
 *
 * WALL JOINTS:
 *   All horizontal (EW, yaw=0) walls are "through" walls ÔÇö they extend
 *   to the outer face of the building, covering corner joints.
 *   All vertical (NS, yaw=90) walls are "between" walls ÔÇö they run
 *   between the inner faces of the horizontal walls.
 *
 * TOTAL AREA: ~120 m┬▓
 */
export function createSimple3BedTemplate(
    budget: number = 200000,
    currency: string = 'EUR'
): PSGProject {
    const project = createEmptyProject('Simple 3-Bedroom Home', budget, currency);
    const rootId = project.root_node_id;

    const H = DEFAULTS.WALL_HEIGHT;     // 2.7m
    const T = DEFAULTS.WALL_THICKNESS;  // 0.25m
    const halfH = H / 2;               // 1.35m ÔÇö center of walls vertically
    const halfT = T / 2;               // 0.125m

    // House outer dimensions
    const HOUSE_W = 10;  // meters (X direction)
    const HOUSE_D = 12;  // meters (Z direction)

    // ÔöÇÔöÇÔöÇ Ground Floor ÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇ
    const floor = add(project, createFloorNode(rootId, 0, 'Ground Floor'));

    // ÔöÇÔöÇÔöÇ Foundation ÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇ
    add(project, createFoundationNode(floor.id, 'Foundation',
        { x: HOUSE_W / 2, y: -0.15, z: HOUSE_D / 2 },
        { x: HOUSE_W + T, y: 0.3, z: HOUSE_D + T }));

    // ÔöÇÔöÇÔöÇ Ground Slab ÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇ
    add(project, createSlabNode(floor.id, 'Ground Floor Slab',
        { x: HOUSE_W / 2, y: 0, z: HOUSE_D / 2 },
        { x: HOUSE_W, y: 0.15, z: HOUSE_D }));

    // ÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇ
    // ROOMS
    // ÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇ
    const living = add(project, createRoomNode(floor.id, 'Living Room',
        { x: HOUSE_W / 2, y: 0, z: 3 },
        { x: HOUSE_W, y: H, z: 6 }, 'living'));

    const kitchen = add(project, createRoomNode(floor.id, 'Kitchen',
        { x: 2.5, y: 0, z: 7.5 },
        { x: 5, y: H, z: 3 }, 'kitchen'));

    const bathroom = add(project, createRoomNode(floor.id, 'Bathroom',
        { x: 7.5, y: 0, z: 7.5 },
        { x: 5, y: H, z: 3 }, 'bathroom'));
    bathroom.tags = ['wet_room'];

    const bed1 = add(project, createRoomNode(floor.id, 'Bedroom 1',
        { x: 2.5, y: 0, z: 10.5 },
        { x: 5, y: H, z: 3 }, 'bedroom'));

    const bed2 = add(project, createRoomNode(floor.id, 'Bedroom 2',
        { x: 7.5, y: 0, z: 10.5 },
        { x: 5, y: H, z: 3 }, 'bedroom'));

    // ÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇ
    // EXTERIOR WALLS ÔÇö "THROUGH" (EW) + "BETWEEN" (NS)
    // ÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇ
    //
    // Through walls (EW, yaw=0): positioned at z = grid ┬▒ T/2,
    //   length = HOUSE_W (inner span, since NS walls butt against them)
    //   BUT we want the EW walls to be the "through" walls, so they span
    //   the FULL outer width.
    //
    // Actually the cleanest approach: EW walls span exactly HOUSE_W,
    // NS walls span exactly their interior span, AND the EW walls sit
    // at the exact grid line (z=0, z=12) with their center at z=halfT
    // so the OUTER face is at z=0.

    // ÔöÇÔöÇ NORTH WALL (z=0 outer face) ÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇ
    // Center: x=HOUSE_W/2, z=halfT (outer face at z=0, inner face at z=T)
    const northWall = addWall(project, living.id, 'North Wall',
        { x: HOUSE_W / 2, y: halfH, z: halfT },
        HOUSE_W, H, T, ['load_bearing', 'exterior']);
    // Windows on the north wall
    add(project, createWindowNode(northWall.id, 'Living Window L',
        { x: 3, y: DEFAULTS.WINDOW_SILL_HEIGHT + 0.7, z: halfT },
        1.8, 1.4));
    add(project, createWindowNode(northWall.id, 'Living Window R',
        { x: 7, y: DEFAULTS.WINDOW_SILL_HEIGHT + 0.7, z: halfT },
        1.8, 1.4));
    // Front door
    add(project, createDoorNode(northWall.id, 'Front Door',
        { x: 5, y: DEFAULTS.DOOR_HEIGHT / 2, z: halfT },
        1.0, DEFAULTS.DOOR_HEIGHT));

    // ÔöÇÔöÇ SOUTH WALL (z=12 outer face) ÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇ
    // Center: z = HOUSE_D - halfT (outer face at z=12, inner face at z=12-T)
    const southWall = addWall(project, bed1.id, 'South Wall',
        { x: HOUSE_W / 2, y: halfH, z: HOUSE_D - halfT },
        HOUSE_W, H, T, ['load_bearing', 'exterior']);
    add(project, createWindowNode(southWall.id, 'Bed 1 Window',
        { x: 2.5, y: DEFAULTS.WINDOW_SILL_HEIGHT + 0.7, z: HOUSE_D - halfT },
        1.4, 1.4));
    add(project, createWindowNode(southWall.id, 'Bed 2 Window',
        { x: 7.5, y: DEFAULTS.WINDOW_SILL_HEIGHT + 0.7, z: HOUSE_D - halfT },
        1.4, 1.4));

    // ÔöÇÔöÇ WEST WALL (x=0 outer face) ÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇ
    // "Between" wall ÔÇö runs from inner face of north wall (z=T)
    // to inner face of south wall (z=HOUSE_D-T)
    const westSpan = HOUSE_D - 2 * T; // 12 - 0.5 = 11.5m
    const westCenterZ = HOUSE_D / 2;  // 6m
    addWall(project, living.id, 'West Wall',
        { x: halfT, y: halfH, z: westCenterZ },
        westSpan, H, T, ['load_bearing', 'exterior'], 90);

    // ÔöÇÔöÇ EAST WALL (x=10 outer face) ÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇ
    const eastWall = addWall(project, bathroom.id, 'East Wall',
        { x: HOUSE_W - halfT, y: halfH, z: westCenterZ },
        westSpan, H, T, ['load_bearing', 'exterior'], 90);
    // Kitchen window (on the west wall section ÔÇö actually let's put a bathroom window on east)
    add(project, createWindowNode(eastWall.id, 'Bathroom Window',
        { x: HOUSE_W - halfT, y: DEFAULTS.WINDOW_SILL_HEIGHT + 0.7, z: 7.5 },
        0.8, 0.6));

    // ÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇ
    // INTERIOR DIVIDERS (Partitions)
    // ÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇ

    // Horizontal divider at Z=6 (between living and kitchen/bath)
    // "Through" partition ÔÇö spans full house width, sits INSIDE
    const PT = 0.15; // partition thickness
    const halfPT = PT / 2;
    const livingDivider = addPartition(project, floor.id, 'Living-Kitchen Divider',
        { x: HOUSE_W / 2, y: halfH, z: 6 },
        HOUSE_W - 2 * T, H, PT);
    add(project, createDoorNode(livingDivider.id, 'Kitchen Door',
        { x: 2.5, y: DEFAULTS.DOOR_HEIGHT / 2, z: 6 },
        0.9, DEFAULTS.DOOR_HEIGHT));

    // Horizontal divider at Z=9 (between kitchen/bath and bedrooms)
    const midDivider = addPartition(project, floor.id, 'Mid Floor Divider',
        { x: HOUSE_W / 2, y: halfH, z: 9 },
        HOUSE_W - 2 * T, H, PT);
    add(project, createDoorNode(midDivider.id, 'Bed 1 Door',
        { x: 2.5, y: DEFAULTS.DOOR_HEIGHT / 2, z: 9 },
        0.9, DEFAULTS.DOOR_HEIGHT));
    add(project, createDoorNode(midDivider.id, 'Bed 2 Door',
        { x: 7.5, y: DEFAULTS.DOOR_HEIGHT / 2, z: 9 },
        0.9, DEFAULTS.DOOR_HEIGHT));

    // Vertical partition at X=5 between kitchen and bathroom (Z=6 to Z=9)
    // "Between" ÔÇö runs between inner faces of horizontal dividers
    const kitchenBathPart = addPartition(project, floor.id, 'Kitchen-Bath Partition',
        { x: 5, y: halfH, z: 7.5 },
        3 - PT, H, 0.12, 90);

    // Vertical partition at X=5 between bedroom 1 and 2 (Z=9 to Z=12)
    addPartition(project, floor.id, 'Bedroom Partition',
        { x: 5, y: halfH, z: 10.5 },
        3 - PT, H, 0.12, 90);

    // ÔöÇÔöÇ Kitchen window (west wall) ÔÇö add as a window on the west wall
    // We can't add to a wall that doesn't cover that range, so let's add
    // a dedicated kitchen west window on the main west wall
    // The west wall already covers z=T to z=HOUSE_D-T which includes z=7.5

    // ÔöÇÔöÇÔöÇ Roof ÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇ
    const roof = add(project, createRoofNode(rootId, 'Main Roof', 'gable', 35,
        { x: HOUSE_W + 1, y: 0.3, z: HOUSE_D + 1 }));
    roof.position = { x: HOUSE_W / 2, y: H, z: HOUSE_D / 2 };

    return project;
}

